// ════════════════════════════════════════════════════════════
// PartyRecruitBoard — 파티 모집 게시판 (Reference B: 컴팩트 리스트)
//   - raid_schedules에서 오늘 이후의 레이드를 가져와 모집글로 표시
//   - 필터(전체/모집중/마감/내가 만든) + 검색 + 등록 버튼
//   - 행 클릭 시 기존 raid 상세 모달(openRaidById 이벤트) 호출
//   - 등록은 RaidCalendar 모달 열어서 기존 흐름 재활용
// ════════════════════════════════════════════════════════════
const PartyRecruitBoard = ({ user, profile, onOpenCalendar }: any) => {
  const [raids, setRaids] = useState<any[]>([]);
  const [participantsMap, setParticipantsMap] = useState<Record<string, any[]>>({});
  const [contentImgMap, setContentImgMap] = useState<Record<string, string>>({});
  const [tab, setTab] = useState<"all" | "open" | "closed" | "mine">("all");
  const [query, setQuery] = useState("");
  const [loading, setLoading] = useState(true);

  const fetchRaids = useCallback(async () => {
    if (!supabase) { setLoading(false); return; }
    setLoading(true);
    try {
      const today = getTodayKey();
      // 오늘 이후 ~ 30일 후까지의 raid_schedules
      const horizon = (() => {
        const d = new Date();
        d.setDate(d.getDate() + 30);
        return formatDate(d.getFullYear(), d.getMonth(), d.getDate());
      })();
      const { data, error } = await supabase
        .from("raid_schedules")
        .select("*")
        .gte("raid_date", today)
        .lte("raid_date", horizon)
        .order("raid_date", { ascending: true })
        .order("raid_time", { ascending: true });
      if (error) throw error;
      const list = data || [];
      setRaids(list);

      // 참여자 일괄 조회
      const ids = list.map((r: any) => r.id).filter(Boolean);
      if (ids.length > 0) {
        const { data: parts } = await supabase
          .from("raid_participants")
          .select("schedule_id, character_name, class_name, position, item_level")
          .in("schedule_id", ids);
        const map: Record<string, any[]> = {};
        (parts || []).forEach((p: any) => {
          const k = String(p.schedule_id);
          if (!map[k]) map[k] = [];
          map[k].push(p);
        });
        setParticipantsMap(map);
      } else {
        setParticipantsMap({});
      }

      // 콘텐츠 이미지
      const names = Array.from(new Set(list.map((r: any) => String(r.raid_name || "").trim()).filter(Boolean)));
      if (names.length > 0) {
        const { data: contents } = await supabase
          .from("contents")
          .select("name, image_url")
          .in("name", names);
        const imgMap: Record<string, string> = {};
        (contents || []).forEach((c: any) => {
          if (c.name && c.image_url) imgMap[String(c.name).trim()] = c.image_url;
        });
        setContentImgMap(imgMap);
      }
    } catch (err) {
      console.error("[PartyRecruitBoard] fetch error:", err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { void fetchRaids(); }, [fetchRaids]);

  // 통계
  const stats = useMemo(() => {
    const now = Date.now();
    let open = 0, closed = 0, mine = 0;
    raids.forEach(r => {
      const max = Number(r.max_participants) || (r.raid_type === "4인" ? 4 : 8);
      const cnt = (participantsMap[String(r.id)] || []).length;
      const isFull = cnt >= max;
      const dateTime = new Date(`${r.raid_date}T${r.raid_time || "00:00"}:00`).getTime();
      if (!isFull && dateTime > now) open++;
      else closed++;
      if (r.leader_id === user?.id || (participantsMap[String(r.id)] || []).some((p: any) => p.character_name === profile?.character_name)) {
        mine++;
      }
    });
    return { open, closed, mine, total: raids.length };
  }, [raids, participantsMap, user?.id, profile?.character_name]);

  // 필터링
  const filtered = useMemo(() => {
    const now = Date.now();
    let result = raids;
    if (tab === "open") {
      result = result.filter(r => {
        const max = Number(r.max_participants) || (r.raid_type === "4인" ? 4 : 8);
        const cnt = (participantsMap[String(r.id)] || []).length;
        const dateTime = new Date(`${r.raid_date}T${r.raid_time || "00:00"}:00`).getTime();
        return cnt < max && dateTime > now;
      });
    } else if (tab === "closed") {
      result = result.filter(r => {
        const max = Number(r.max_participants) || (r.raid_type === "4인" ? 4 : 8);
        const cnt = (participantsMap[String(r.id)] || []).length;
        const dateTime = new Date(`${r.raid_date}T${r.raid_time || "00:00"}:00`).getTime();
        return cnt >= max || dateTime <= now;
      });
    } else if (tab === "mine") {
      result = result.filter(r =>
        r.leader_id === user?.id ||
        (participantsMap[String(r.id)] || []).some((p: any) => p.character_name === profile?.character_name)
      );
    }
    if (query.trim()) {
      const q = query.toLowerCase().trim();
      result = result.filter((r: any) =>
        String(r.raid_name || "").toLowerCase().includes(q) ||
        String(r.leader_name || "").toLowerCase().includes(q) ||
        String(r.difficulty || "").toLowerCase().includes(q)
      );
    }
    return result;
  }, [raids, tab, query, participantsMap, user?.id, profile?.character_name]);

  const formatRelativeDate = (dateStr: string, timeStr: string) => {
    if (!dateStr) return "";
    const [y, m, d] = String(dateStr).split("-").map(Number);
    if (!y) return "";
    const target = new Date(y, m - 1, d);
    const today = new Date(); today.setHours(0,0,0,0);
    const diffDays = Math.round((target.getTime() - today.getTime()) / 86400000);
    const dayKr = ["일","월","화","수","목","금","토"][target.getDay()];
    const time = timeStr ? ` ${timeStr}` : "";
    if (diffDays === 0) return `오늘${time}`;
    if (diffDays === 1) return `내일${time}`;
    if (diffDays === 2) return `모레${time}`;
    if (diffDays < 7) return `${m}/${d} (${dayKr})${time}`;
    return `${m}/${d} (${dayKr})${time}`;
  };

  const formatTimeAgo = (iso?: string) => {
    if (!iso) return "";
    const t = new Date(iso).getTime();
    const diff = Math.max(0, Date.now() - t);
    const m = Math.floor(diff / 60000);
    if (m < 1) return "방금 전";
    if (m < 60) return `${m}분 전`;
    const h = Math.floor(m / 60);
    if (h < 24) return `${h}시간 전`;
    const d = Math.floor(h / 24);
    return `${d}일 전`;
  };

  const openRaidDetail = (raid: any) => {
    onOpenCalendar?.();
    setTimeout(() => {
      window.dispatchEvent(new CustomEvent("openRaidById", { detail: { raidId: raid.id } }));
    }, 350);
  };

  const TABS: Array<{ key: typeof tab; label: string; count: number; color: string }> = [
    { key: "all",    label: "전체",    count: stats.total,  color: "#a78bfa" },
    { key: "open",   label: "모집중",  count: stats.open,   color: "#67e8f9" },
    { key: "closed", label: "마감",    count: stats.closed, color: "rgba(196,181,253,0.6)" },
    { key: "mine",   label: "내 모집", count: stats.mine,   color: "#f472b6" },
  ];

  return (
    <div className="space-y-4 lg:space-y-5">
      {/* 헤더 */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <div className="text-[11px] font-bold uppercase tracking-[0.22em]" style={{ color: "#c4b5fd" }}>
            Party Recruitment
          </div>
          <h1 className="text-2xl font-bold text-white mt-1">파티 모집</h1>
          <p className="text-xs mt-1" style={{ color: "rgba(155,159,196,0.7)" }}>
            예정된 레이드에 참여하거나 새 모집글을 등록해보세요
          </p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={fetchRaids}
            className="flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-semibold transition-all"
            style={{
              background: "rgba(255,255,255,0.04)",
              border: "1px solid rgba(255,255,255,0.06)",
              color: "rgba(196,181,253,0.85)",
            }}
          >
            <RefreshCw size={12} />
            새로고침
          </button>
          <button
            onClick={() => onOpenCalendar?.()}
            className="flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs font-bold text-white transition-all"
            style={{
              background: "linear-gradient(135deg, #8b5cf6, #6d28d9)",
              boxShadow: "0 8px 24px rgba(139,92,246,0.30)",
            }}
          >
            <Plus size={13} />
            모집 등록
          </button>
        </div>
      </div>

      {/* 탭 */}
      <div className="flex gap-0 border-b" style={{ borderColor: "rgba(255,255,255,0.06)" }}>
        {TABS.map(t => (
          <button
            key={t.key}
            onClick={() => setTab(t.key)}
            className="px-4 py-2.5 text-xs font-semibold transition-colors relative"
            style={{
              color: tab === t.key ? "#fff" : "rgba(196,181,253,0.6)",
              borderBottom: tab === t.key ? `2px solid ${t.color}` : "2px solid transparent",
              marginBottom: "-1px",
            }}
          >
            {t.label}
            {t.count > 0 && (
              <span className="ml-1.5" style={{ color: t.color, fontWeight: 700 }}>{t.count}</span>
            )}
          </button>
        ))}
      </div>

      {/* 검색 */}
      <div
        className="flex items-center gap-2 px-3 py-2 rounded-xl"
        style={{
          background: "rgba(255,255,255,0.04)",
          border: "1px solid rgba(255,255,255,0.06)",
        }}
      >
        <Search size={14} style={{ color: "rgba(196,181,253,0.5)" }} />
        <input
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="레이드명, 공대장, 난이도로 검색"
          className="flex-1 bg-transparent outline-none text-xs"
          style={{ color: "#fff" }}
        />
        {query && (
          <button onClick={() => setQuery("")} className="text-xs" style={{ color: "rgba(196,181,253,0.6)" }}>
            <X size={13} />
          </button>
        )}
      </div>

      {/* 리스트 */}
      <div className="space-y-1.5">
        {loading ? (
          <div className="text-center py-12 text-xs" style={{ color: "rgba(155,159,196,0.5)" }}>
            데이터를 불러오는 중...
          </div>
        ) : filtered.length === 0 ? (
          <div className="text-center py-16 px-4 rounded-2xl"
            style={{
              background: "linear-gradient(180deg, rgba(28,23,51,0.55) 0%, rgba(15,13,32,0.75) 100%)",
              border: "1px solid rgba(139,92,246,0.10)",
            }}>
            <div className="text-4xl mb-2" style={{ color: "rgba(196,181,253,0.3)" }}>📭</div>
            <div className="text-sm font-semibold text-white mb-1">
              {query ? "검색 결과가 없습니다" : tab === "mine" ? "내가 만든 모집글이 없습니다" : "모집글이 없습니다"}
            </div>
            <div className="text-xs" style={{ color: "rgba(155,159,196,0.5)" }}>
              상단의 "모집 등록" 버튼으로 새 레이드를 만들어보세요
            </div>
          </div>
        ) : filtered.map((r: any) => {
          const max = Number(r.max_participants) || (r.raid_type === "4인" ? 4 : 8);
          const parts = participantsMap[String(r.id)] || [];
          const cnt = parts.length;
          const dateTime = new Date(`${r.raid_date}T${r.raid_time || "00:00"}:00`).getTime();
          const isFull = cnt >= max;
          const isPast = dateTime <= Date.now();
          const isClosed = isFull || isPast;
          const isImminent = !isClosed && (max - cnt) <= 1;
          const img = contentImgMap[String(r.raid_name || "").trim()];

          // 행 컬러 톤
          let toneR = "139,92,246"; // 보라 기본
          let toneText = "#a78bfa";
          let btnBg = "linear-gradient(135deg, #8b5cf6, #6d28d9)";
          let btnText = "#fff";
          let btnLabel = "참여";
          if (isClosed) {
            toneR = "155,159,196";
            toneText = "rgba(196,181,253,0.55)";
            btnBg = "rgba(255,255,255,0.04)";
            btnText = "rgba(155,159,196,0.6)";
            btnLabel = isFull ? "마감" : "종료";
          } else if (isImminent) {
            toneR = "244,114,182";
            toneText = "#f472b6";
            btnBg = "rgba(244,114,182,0.18)";
            btnText = "#f9a8d4";
            btnLabel = `${max - cnt}자리`;
          } else if (r.type === "anime") {
            toneR = "34,211,238";
            toneText = "#67e8f9";
            btnBg = "linear-gradient(135deg, #22d3ee, #0891b2)";
          }

          return (
            <button
              key={r.id}
              onClick={() => openRaidDetail(r)}
              className="w-full grid items-center gap-3 px-3 py-2.5 rounded-xl transition-all text-left hover:translate-x-0.5"
              style={{
                gridTemplateColumns: "56px 1fr auto auto",
                background: `rgba(${toneR},0.04)`,
                border: `1px solid rgba(${toneR},0.14)`,
                cursor: "pointer",
              }}
              onMouseEnter={(e) => {
                (e.currentTarget as HTMLElement).style.background = `rgba(${toneR},0.10)`;
                (e.currentTarget as HTMLElement).style.borderColor = `rgba(${toneR},0.28)`;
              }}
              onMouseLeave={(e) => {
                (e.currentTarget as HTMLElement).style.background = `rgba(${toneR},0.04)`;
                (e.currentTarget as HTMLElement).style.borderColor = `rgba(${toneR},0.14)`;
              }}
            >
              {/* 아이콘 */}
              <div
                className="w-14 h-14 rounded-xl flex items-center justify-center flex-shrink-0 overflow-hidden"
                style={{
                  background: img
                    ? `url(${img}) center/cover`
                    : `radial-gradient(ellipse at 50% 30%, rgba(${toneR},0.30), #1c1733)`,
                }}
              >
                {!img && <Shield size={22} style={{ color: toneText }} />}
              </div>

              {/* 정보 */}
              <div className="min-w-0">
                <div className="flex items-center gap-1 mb-1 flex-wrap">
                  {r.difficulty && (
                    <span className="px-1.5 py-0.5 rounded text-[9px] font-bold"
                      style={{ background: "rgba(244,114,182,0.18)", color: "#f9a8d4" }}>
                      {r.difficulty}
                    </span>
                  )}
                  {r.experience && (
                    <span className="px-1.5 py-0.5 rounded text-[9px] font-bold"
                      style={{ background: "rgba(110,231,183,0.18)", color: "#6ee7b7" }}>
                      {r.experience}
                    </span>
                  )}
                  {r.raid_type && (
                    <span className="px-1.5 py-0.5 rounded text-[9px] font-bold"
                      style={{ background: "rgba(167,139,250,0.18)", color: "#c4b5fd" }}>
                      {r.raid_type}
                    </span>
                  )}
                  {isImminent && (
                    <span className="px-1.5 py-0.5 rounded text-[9px] font-bold flex items-center gap-1"
                      style={{ background: "rgba(251,191,36,0.18)", color: "#fbbf24" }}>
                      🔥 마감 임박
                    </span>
                  )}
                  <span className="text-[9px] ml-1" style={{ color: "rgba(155,159,196,0.5)" }}>
                    {formatTimeAgo(r.created_at)}
                  </span>
                </div>
                <div className="text-sm font-bold text-white truncate mb-0.5">
                  {r.raid_name || "이름 없음"}
                </div>
                <div className="text-[10px] flex items-center gap-3 flex-wrap" style={{ color: "rgba(155,159,196,0.7)" }}>
                  <span className="flex items-center gap-1">
                    <Clock size={10} />
                    {formatRelativeDate(r.raid_date, r.raid_time)}
                  </span>
                  {r.leader_name && (
                    <span className="flex items-center gap-1">
                      <Crown size={10} style={{ color: "#fbbf24" }} />
                      {r.leader_name}
                    </span>
                  )}
                </div>
              </div>

              {/* 참여 인원 */}
              <div className="text-right flex-shrink-0">
                <div className="text-xs font-bold" style={{ color: toneText }}>
                  {cnt} / {max}
                </div>
                <div className="mt-1 w-14 h-0.5 rounded-full overflow-hidden" style={{ background: "rgba(255,255,255,0.05)" }}>
                  <div
                    className="h-full rounded-full"
                    style={{
                      width: `${Math.min(100, (cnt / max) * 100)}%`,
                      background: `linear-gradient(90deg, rgba(${toneR},1), rgba(${toneR},0.6))`,
                    }}
                  />
                </div>
              </div>

              {/* 액션 */}
              <div
                className="px-3 py-1.5 rounded-lg text-xs font-bold flex-shrink-0 transition-all"
                style={{
                  background: btnBg,
                  color: btnText,
                  border: isClosed ? "1px solid rgba(255,255,255,0.06)" : "none",
                  boxShadow: !isClosed && !isImminent ? "0 4px 12px rgba(139,92,246,0.20)" : "none",
                }}
              >
                {btnLabel}
              </div>
            </button>
          );
        })}
      </div>

      {!loading && filtered.length > 0 && (
        <div className="text-center text-[10px] pt-2" style={{ color: "rgba(155,159,196,0.4)" }}>
          {filtered.length}개의 모집글 표시 중
        </div>
      )}
    </div>
  );
};


// ════════════════════════════════════════════════════════════
// RaidHistoryDetailModal — 레이드 기록 상세 모달
//   - 카드 클릭 시 레이드 전체 정보 + 참여자 상세 표시
// ════════════════════════════════════════════════════════════
const RaidHistoryDetailModal = ({ raid, participants, contentImg, onClose, profile }: any) => {
  if (!raid) return null;

  const max = Number(raid.max_participants) || (raid.raid_type === "4인" ? 4 : 8);
  const cnt = participants.length;
  const myCharName = profile?.character_name || profile?.nickname;

  // 날짜 포맷
  const dateLabel = (() => {
    const [y, m, d] = String(raid.raid_date || "").split("-").map(Number);
    if (!y) return raid.raid_date;
    const dd = new Date(y, m - 1, d);
    const dayKr = ["일", "월", "화", "수", "목", "금", "토"][dd.getDay()];
    return `${y}년 ${m}월 ${d}일 (${dayKr})`;
  })();

  // 클래스별 카운트
  const classCounts = participants.reduce((acc: Record<string, number>, p: any) => {
    const cls = String(p.class_name || "미정").trim();
    acc[cls] = (acc[cls] || 0) + 1;
    return acc;
  }, {});

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 z-50 flex items-center justify-center p-4"
        style={{
          background: "rgba(8, 6, 18, 0.78)",
          backdropFilter: "blur(8px)",
        }}
        onClick={onClose}
      >
        <motion.div
          initial={{ opacity: 0, y: 20, scale: 0.96 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          exit={{ opacity: 0, y: 10, scale: 0.97 }}
          transition={{ duration: 0.2 }}
          className="relative w-full max-w-2xl max-h-[90vh] overflow-y-auto rounded-3xl"
          style={{
            background: "linear-gradient(180deg, rgba(28,23,51,0.98) 0%, rgba(15,13,32,0.99) 100%)",
            border: "1px solid rgba(139,92,246,0.25)",
            boxShadow: "0 30px 80px rgba(0,0,0,0.55)",
          }}
          onClick={(e) => e.stopPropagation()}
        >
          {/* 닫기 */}
          <button
            onClick={onClose}
            className="absolute top-4 right-4 z-20 w-8 h-8 rounded-full flex items-center justify-center transition-all"
            style={{
              background: "rgba(255,255,255,0.06)",
              border: "1px solid rgba(255,255,255,0.10)",
              color: "rgba(196,181,253,0.85)",
            }}
            onMouseEnter={(e) => { (e.currentTarget as HTMLElement).style.background = "rgba(244,114,182,0.18)"; }}
            onMouseLeave={(e) => { (e.currentTarget as HTMLElement).style.background = "rgba(255,255,255,0.06)"; }}
          >
            <X size={15} />
          </button>

          {/* 상단 히어로 영역 (콘텐츠 이미지 배경) */}
          <div
            className="relative px-6 pt-6 pb-5"
            style={{
              background: contentImg
                ? `linear-gradient(180deg, rgba(15,12,30,0.55) 0%, rgba(15,13,32,0.95) 100%), url(${contentImg}) center/cover no-repeat`
                : "linear-gradient(160deg, rgba(76,29,149,0.30) 0%, rgba(15,13,32,0.85) 100%)",
              minHeight: 140,
            }}
          >
            <div className="flex items-center gap-2 mb-2 flex-wrap">
              <span
                className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md text-[10px] font-bold uppercase tracking-[0.18em]"
                style={{
                  background: "rgba(110,231,183,0.18)",
                  color: "#6ee7b7",
                  border: "1px solid rgba(110,231,183,0.30)",
                }}
              >
                <span className="w-1.5 h-1.5 rounded-full" style={{ background: "#6ee7b7" }} />
                Raid Record
              </span>
              {raid.difficulty && (
                <span className="px-2.5 py-1 rounded-md text-[11px] font-bold"
                  style={{ background: "rgba(244,114,182,0.18)", color: "#f9a8d4", border: "1px solid rgba(244,114,182,0.30)" }}>
                  {raid.difficulty}
                </span>
              )}
              {raid.experience && (
                <span className="px-2.5 py-1 rounded-md text-[11px] font-bold"
                  style={{ background: "rgba(110,231,183,0.18)", color: "#6ee7b7", border: "1px solid rgba(110,231,183,0.30)" }}>
                  {raid.experience}
                </span>
              )}
              {raid.raid_type && (
                <span className="px-2.5 py-1 rounded-md text-[11px] font-bold"
                  style={{ background: "rgba(167,139,250,0.18)", color: "#c4b5fd", border: "1px solid rgba(167,139,250,0.30)" }}>
                  {raid.raid_type}
                </span>
              )}
            </div>
            <h2 className="text-2xl font-bold text-white tracking-tight">
              {raid.raid_name || "이름 없음"}
            </h2>
            <div className="mt-2 flex items-center gap-4 text-xs flex-wrap" style={{ color: "rgba(196,181,253,0.85)" }}>
              <span className="flex items-center gap-1.5">
                <CalendarDays size={13} />
                {dateLabel}
              </span>
              <span className="flex items-center gap-1.5">
                <Clock size={13} />
                {raid.raid_time || "시간 미정"}
                {raid.raid_end_time && ` ~ ${raid.raid_end_time}`}
              </span>
            </div>
          </div>

          {/* 본문 */}
          <div className="p-6 space-y-5">
            {/* 통계 4분할 */}
            <div className="grid grid-cols-4 gap-2">
              <div className="rounded-xl p-3 text-center"
                style={{ background: "rgba(255,255,255,0.03)", border: "1px solid rgba(255,255,255,0.06)" }}>
                <div className="text-[9px] font-semibold uppercase tracking-wider mb-1"
                  style={{ color: "rgba(155,159,196,0.55)" }}>참여 인원</div>
                <div className="text-lg font-bold text-white">
                  {cnt}<span className="text-xs font-normal ml-0.5" style={{ color: "rgba(155,159,196,0.5)" }}>/{max}</span>
                </div>
              </div>
              <div className="rounded-xl p-3 text-center"
                style={{ background: "rgba(255,255,255,0.03)", border: "1px solid rgba(255,255,255,0.06)" }}>
                <div className="text-[9px] font-semibold uppercase tracking-wider mb-1"
                  style={{ color: "rgba(155,159,196,0.55)" }}>충원율</div>
                <div className="text-lg font-bold" style={{ color: "#a78bfa" }}>
                  {Math.round((cnt / Math.max(1, max)) * 100)}<span className="text-xs font-normal ml-0.5">%</span>
                </div>
              </div>
              <div className="rounded-xl p-3 text-center"
                style={{ background: "rgba(255,255,255,0.03)", border: "1px solid rgba(255,255,255,0.06)" }}>
                <div className="text-[9px] font-semibold uppercase tracking-wider mb-1"
                  style={{ color: "rgba(155,159,196,0.55)" }}>클래스 수</div>
                <div className="text-lg font-bold" style={{ color: "#67e8f9" }}>
                  {Object.keys(classCounts).length}
                </div>
              </div>
              <div className="rounded-xl p-3 text-center"
                style={{ background: "rgba(251,191,36,0.05)", border: "1px solid rgba(251,191,36,0.18)" }}>
                <div className="text-[9px] font-semibold uppercase tracking-wider mb-1"
                  style={{ color: "rgba(251,191,36,0.7)" }}>공대장</div>
                <div className="text-sm font-bold truncate" style={{ color: "#fbbf24" }}>
                  {raid.leader_name || "—"}
                </div>
              </div>
            </div>

            {/* 참여자 명단 */}
            <div>
              <div className="flex items-center justify-between mb-2">
                <h3 className="text-sm font-bold text-white flex items-center gap-2">
                  <Users size={14} style={{ color: "#a78bfa" }} />
                  참여자 명단
                </h3>
                <span className="text-[10px]" style={{ color: "rgba(155,159,196,0.6)" }}>
                  총 {cnt}명
                </span>
              </div>

              {participants.length === 0 ? (
                <div className="text-center py-8 rounded-xl text-xs"
                  style={{
                    background: "rgba(255,255,255,0.02)",
                    border: "1px solid rgba(255,255,255,0.04)",
                    color: "rgba(155,159,196,0.5)",
                  }}>
                  참여자 정보가 없습니다
                </div>
              ) : (
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                  {participants.map((p: any, i: number) => {
                    const isMe = p.character_name === myCharName;
                    return (
                      <div
                        key={i}
                        className="flex items-center gap-3 px-3 py-2 rounded-xl"
                        style={{
                          background: isMe ? "rgba(139,92,246,0.10)" : "rgba(255,255,255,0.03)",
                          border: isMe ? "1px solid rgba(139,92,246,0.28)" : "1px solid rgba(255,255,255,0.06)",
                        }}
                      >
                        {/* 아바타 */}
                        <div
                          className="w-8 h-8 rounded-lg flex items-center justify-center text-xs font-bold flex-shrink-0"
                          style={{
                            background: "linear-gradient(135deg, #6d28d9, #4c1d95)",
                            color: "#ede9fe",
                            border: "1px solid rgba(139,92,246,0.30)",
                          }}
                        >
                          {String(p.character_name || "?").slice(0, 1)}
                        </div>
                        {/* 정보 */}
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-1.5">
                            <span className="text-xs font-bold text-white truncate">
                              {p.character_name || "이름 없음"}
                            </span>
                            {isMe && (
                              <span className="px-1.5 py-0 rounded text-[8px] font-bold flex-shrink-0"
                                style={{
                                  background: "rgba(139,92,246,0.25)",
                                  color: "#c4b5fd",
                                }}>
                                나
                              </span>
                            )}
                            {p.character_name === raid.leader_name && (
                              <Crown size={10} style={{ color: "#fbbf24", flexShrink: 0 }} />
                            )}
                          </div>
                          <div className="text-[10px] flex items-center gap-2 mt-0.5"
                            style={{ color: "rgba(155,159,196,0.7)" }}>
                            <span className="truncate">{p.class_name || "직업 미정"}</span>
                            {p.item_level && (
                              <span className="text-[10px] font-bold" style={{ color: "#fbbf24" }}>
                                {p.item_level}
                              </span>
                            )}
                          </div>
                        </div>
                        {/* 포지션 */}
                        {p.position && (
                          <span className="px-2 py-0.5 rounded text-[9px] font-bold flex-shrink-0"
                            style={{
                              background: p.position.includes("딜") || p.position.includes("dps")
                                ? "rgba(244,114,182,0.14)"
                                : p.position.includes("서폿") || p.position.includes("sup")
                                  ? "rgba(110,231,183,0.14)"
                                  : "rgba(167,139,250,0.14)",
                              color: p.position.includes("딜") || p.position.includes("dps")
                                ? "#f9a8d4"
                                : p.position.includes("서폿") || p.position.includes("sup")
                                  ? "#6ee7b7"
                                  : "#c4b5fd",
                            }}>
                            {p.position}
                          </span>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}
            </div>

            {/* 클래스 구성 */}
            {Object.keys(classCounts).length > 0 && (
              <div>
                <h3 className="text-sm font-bold text-white mb-2 flex items-center gap-2">
                  <Sparkles size={14} style={{ color: "#a78bfa" }} />
                  클래스 구성
                </h3>
                <div className="flex flex-wrap gap-1.5">
                  {Object.entries(classCounts).map(([cls, count]) => (
                    <span
                      key={cls}
                      className="px-2.5 py-1 rounded-lg text-[11px] font-bold flex items-center gap-1"
                      style={{
                        background: "rgba(167,139,250,0.10)",
                        border: "1px solid rgba(167,139,250,0.20)",
                        color: "#c4b5fd",
                      }}
                    >
                      {cls}
                      <span className="text-[10px] opacity-80">×{count as number}</span>
                    </span>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* 푸터 */}
          <div className="px-6 pb-5 pt-2">
            <div className="flex items-center justify-between text-[10px] py-3 px-4 rounded-xl"
              style={{
                background: "rgba(255,255,255,0.02)",
                border: "1px solid rgba(255,255,255,0.04)",
                color: "rgba(155,159,196,0.6)",
              }}>
              <span>
                <i className="ti ti-info-circle" /> 기록 ID: <code style={{ color: "rgba(196,181,253,0.7)" }}>{String(raid.id || "").slice(0, 8)}</code>
              </span>
              {raid.created_at && (
                <span>
                  생성: {new Date(raid.created_at).toLocaleDateString("ko-KR")}
                </span>
              )}
            </div>
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
};


// ════════════════════════════════════════════════════════════
// RaidHistoryBoard — 레이드 기록 게시판 (Reference A: 타임라인)
//   - raid_schedules에서 오늘 이전(과거)의 레이드를 가져와 기록으로 표시
//   - 날짜별 그룹핑 (오늘/어제/N일전/날짜)
//   - 각 카드: 썸네일 + 레이드명 + 난이도 + 시간 + 참여자 아바타 + 공대장
//   - 필터: 전체/내 기록/이번 주/이번 달
// ════════════════════════════════════════════════════════════
const RaidHistoryBoard = ({ user, profile, onOpenCalendar }: any) => {
  const [raids, setRaids] = useState<any[]>([]);
  const [participantsMap, setParticipantsMap] = useState<Record<string, any[]>>({});
  const [contentImgMap, setContentImgMap] = useState<Record<string, string>>({});
  const [filter, setFilter] = useState<"all" | "mine" | "week" | "month">("all");
  const [loading, setLoading] = useState(true);
  // 상세 모달
  const [detailRaid, setDetailRaid] = useState<any | null>(null);

  const fetchHistory = useCallback(async () => {
    if (!supabase) { setLoading(false); return; }
    setLoading(true);
    try {
      const today = getTodayKey();
      // 오늘 이전 90일치
      const past = (() => {
        const d = new Date();
        d.setDate(d.getDate() - 90);
        return formatDate(d.getFullYear(), d.getMonth(), d.getDate());
      })();
      const { data, error } = await supabase
        .from("raid_schedules")
        .select("*")
        .gte("raid_date", past)
        .lt("raid_date", today)
        .order("raid_date", { ascending: false })
        .order("raid_time", { ascending: false });
      if (error) throw error;
      const list = data || [];
      setRaids(list);

      // 참여자 일괄 조회
      const ids = list.map((r: any) => r.id).filter(Boolean);
      if (ids.length > 0) {
        const { data: parts } = await supabase
          .from("raid_participants")
          .select("schedule_id, character_name, class_name, position, item_level")
          .in("schedule_id", ids);
        const map: Record<string, any[]> = {};
        (parts || []).forEach((p: any) => {
          const k = String(p.schedule_id);
          if (!map[k]) map[k] = [];
          map[k].push(p);
        });
        setParticipantsMap(map);
      } else {
        setParticipantsMap({});
      }

      // 콘텐츠 이미지
      const names = Array.from(new Set(list.map((r: any) => String(r.raid_name || "").trim()).filter(Boolean)));
      if (names.length > 0) {
        const { data: contents } = await supabase
          .from("contents")
          .select("name, image_url")
          .in("name", names);
        const imgMap: Record<string, string> = {};
        (contents || []).forEach((c: any) => {
          if (c.name && c.image_url) imgMap[String(c.name).trim()] = c.image_url;
        });
        setContentImgMap(imgMap);
      }
    } catch (err) {
      console.error("[RaidHistoryBoard] fetch error:", err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { void fetchHistory(); }, [fetchHistory]);

  // 필터링
  const filtered = useMemo(() => {
    let result = raids;
    const now = new Date();
    if (filter === "mine") {
      result = result.filter(r =>
        r.leader_id === user?.id ||
        (participantsMap[String(r.id)] || []).some((p: any) => p.character_name === profile?.character_name)
      );
    } else if (filter === "week") {
      const weekAgo = new Date(now); weekAgo.setDate(now.getDate() - 7);
      result = result.filter(r => new Date(r.raid_date) >= weekAgo);
    } else if (filter === "month") {
      const monthAgo = new Date(now); monthAgo.setDate(now.getDate() - 30);
      result = result.filter(r => new Date(r.raid_date) >= monthAgo);
    }
    return result;
  }, [raids, filter, participantsMap, user?.id, profile?.character_name]);

  // 날짜별 그룹핑
  const grouped = useMemo(() => {
    const groups: Record<string, any[]> = {};
    filtered.forEach(r => {
      const k = String(r.raid_date || "");
      if (!groups[k]) groups[k] = [];
      groups[k].push(r);
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [filtered]);

  const formatGroupHeader = (dateStr: string) => {
    if (!dateStr) return "";
    const [y, m, d] = String(dateStr).split("-").map(Number);
    if (!y) return dateStr;
    const target = new Date(y, m - 1, d);
    const today = new Date(); today.setHours(0,0,0,0);
    const diffDays = Math.round((today.getTime() - target.getTime()) / 86400000);
    const dayKr = ["일","월","화","수","목","금","토"][target.getDay()];
    if (diffDays === 0) return `오늘 · ${m}월 ${d}일 (${dayKr})`;
    if (diffDays === 1) return `어제 · ${m}월 ${d}일 (${dayKr})`;
    if (diffDays < 7) return `${diffDays}일 전 · ${m}월 ${d}일 (${dayKr})`;
    return `${m}월 ${d}일 (${dayKr})`;
  };

  const openRaidDetail = (raid: any) => {
    setDetailRaid(raid);
  };
  const stats = useMemo(() => {
    const total = filtered.length;
    const totalParticipations = filtered.reduce((acc, r) => acc + (participantsMap[String(r.id)] || []).length, 0);
    const myCount = filtered.filter(r => r.leader_id === user?.id || (participantsMap[String(r.id)] || []).some((p: any) => p.character_name === profile?.character_name)).length;
    return { total, totalParticipations, myCount };
  }, [filtered, participantsMap, user?.id, profile?.character_name]);

  const FILTERS: Array<{ key: typeof filter; label: string }> = [
    { key: "all",   label: "전체" },
    { key: "mine",  label: "내 기록" },
    { key: "week",  label: "이번 주" },
    { key: "month", label: "이번 달" },
  ];

  return (
    <div className="space-y-4 lg:space-y-5">
      {/* 헤더 */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <div className="text-[11px] font-bold uppercase tracking-[0.22em]" style={{ color: "#c4b5fd" }}>
            Raid History
          </div>
          <h1 className="text-2xl font-bold text-white mt-1">레이드 기록</h1>
          <p className="text-xs mt-1" style={{ color: "rgba(155,159,196,0.7)" }}>
            지난 레이드 활동을 시간 순으로 확인하세요
          </p>
        </div>
        <div className="flex gap-2 items-center">
          {FILTERS.map(f => (
            <button
              key={f.key}
              onClick={() => setFilter(f.key)}
              className="px-3 py-1.5 rounded-lg text-[11px] font-semibold transition-all"
              style={{
                background: filter === f.key ? "rgba(139,92,246,0.18)" : "rgba(255,255,255,0.04)",
                border: filter === f.key ? "1px solid rgba(139,92,246,0.35)" : "1px solid rgba(255,255,255,0.06)",
                color: filter === f.key ? "#c4b5fd" : "rgba(196,181,253,0.7)",
              }}
            >
              {f.label}
            </button>
          ))}
        </div>
      </div>

      {/* 통계 미니 바 */}
      <div className="grid grid-cols-3 gap-3">
        <div className="rounded-xl p-3 flex items-center gap-3"
          style={{ background: "linear-gradient(180deg, rgba(28,23,51,0.55) 0%, rgba(15,13,32,0.75) 100%)", border: "1px solid rgba(139,92,246,0.14)" }}>
          <div className="w-10 h-10 rounded-lg flex items-center justify-center"
            style={{ background: "rgba(139,92,246,0.14)" }}>
            <Shield size={18} style={{ color: "#a78bfa" }} />
          </div>
          <div>
            <div className="text-[10px] font-semibold uppercase tracking-wider" style={{ color: "rgba(155,159,196,0.6)" }}>총 레이드</div>
            <div className="text-lg font-bold text-white">{stats.total}<span className="text-xs font-normal ml-1" style={{ color: "rgba(155,159,196,0.5)" }}>회</span></div>
          </div>
        </div>
        <div className="rounded-xl p-3 flex items-center gap-3"
          style={{ background: "linear-gradient(180deg, rgba(28,23,51,0.55) 0%, rgba(15,13,32,0.75) 100%)", border: "1px solid rgba(139,92,246,0.14)" }}>
          <div className="w-10 h-10 rounded-lg flex items-center justify-center"
            style={{ background: "rgba(110,231,183,0.14)" }}>
            <Users size={18} style={{ color: "#6ee7b7" }} />
          </div>
          <div>
            <div className="text-[10px] font-semibold uppercase tracking-wider" style={{ color: "rgba(155,159,196,0.6)" }}>총 참여</div>
            <div className="text-lg font-bold" style={{ color: "#6ee7b7" }}>{stats.totalParticipations}<span className="text-xs font-normal ml-1" style={{ color: "rgba(155,159,196,0.5)" }}>명</span></div>
          </div>
        </div>
        <div className="rounded-xl p-3 flex items-center gap-3"
          style={{ background: "linear-gradient(160deg, rgba(76,29,149,0.30) 0%, rgba(15,13,32,0.85) 100%)", border: "1px solid rgba(251,191,36,0.20)" }}>
          <div className="w-10 h-10 rounded-lg flex items-center justify-center"
            style={{ background: "rgba(251,191,36,0.14)" }}>
            <Crown size={18} style={{ color: "#fbbf24" }} />
          </div>
          <div>
            <div className="text-[10px] font-semibold uppercase tracking-wider" style={{ color: "rgba(251,191,36,0.7)" }}>내 참여</div>
            <div className="text-lg font-bold" style={{ color: "#fbbf24" }}>{stats.myCount}<span className="text-xs font-normal ml-1" style={{ color: "rgba(155,159,196,0.5)" }}>회</span></div>
          </div>
        </div>
      </div>

      {/* 타임라인 */}
      {loading ? (
        <div className="text-center py-16 text-xs" style={{ color: "rgba(155,159,196,0.5)" }}>
          데이터를 불러오는 중...
        </div>
      ) : grouped.length === 0 ? (
        <div className="text-center py-16 px-4 rounded-2xl"
          style={{
            background: "linear-gradient(180deg, rgba(28,23,51,0.55) 0%, rgba(15,13,32,0.75) 100%)",
            border: "1px solid rgba(139,92,246,0.10)",
          }}>
          <div className="text-4xl mb-2" style={{ color: "rgba(196,181,253,0.3)" }}>📚</div>
          <div className="text-sm font-semibold text-white mb-1">기록이 없습니다</div>
          <div className="text-xs" style={{ color: "rgba(155,159,196,0.5)" }}>
            완료된 레이드가 여기에 표시됩니다
          </div>
        </div>
      ) : (
        <div className="relative pl-7">
          {/* 세로 라인 */}
          <div className="absolute left-2 top-2 bottom-2 w-px"
            style={{ background: "linear-gradient(180deg, rgba(167,139,250,0.4), rgba(167,139,250,0.05))" }}
          />

          {grouped.map(([dateStr, items], gIdx) => (
            <div key={dateStr} className="mb-6 last:mb-0">
              {/* 날짜 헤더 + 도트 */}
              <div className="relative mb-3">
                <div className="absolute left-[-23px] top-1 w-3.5 h-3.5 rounded-full"
                  style={{
                    background: gIdx === 0 ? "#a78bfa" : "rgba(139,92,246,0.5)",
                    border: "3px solid #15122a",
                    boxShadow: gIdx === 0 ? "0 0 0 1px #a78bfa" : "none",
                  }}
                />
                <div className="text-xs font-bold" style={{ color: gIdx === 0 ? "#a78bfa" : "rgba(196,181,253,0.85)" }}>
                  {formatGroupHeader(dateStr)}
                  <span className="ml-2 font-normal" style={{ color: "rgba(155,159,196,0.5)" }}>
                    · {items.length}건
                  </span>
                </div>
              </div>

              {/* 카드들 */}
              <div className="space-y-2">
                {items.map((r: any) => {
                  const max = Number(r.max_participants) || (r.raid_type === "4인" ? 4 : 8);
                  const parts = participantsMap[String(r.id)] || [];
                  const cnt = parts.length;
                  const completed = cnt >= Math.ceil(max * 0.5); // 절반 이상 모이면 "완료"로 간주
                  const img = contentImgMap[String(r.raid_name || "").trim()];
                  const myParticipation = parts.find((p: any) => p.character_name === profile?.character_name);

                  return (
                    <button
                      key={r.id}
                      onClick={() => openRaidDetail(r)}
                      className="w-full text-left rounded-2xl overflow-hidden transition-all"
                      style={{
                        background: "linear-gradient(180deg, rgba(28,23,51,0.85) 0%, rgba(15,13,32,0.95) 100%)",
                        border: completed
                          ? "1px solid rgba(110,231,183,0.20)"
                          : "1px solid rgba(155,159,196,0.15)",
                      }}
                      onMouseEnter={(e) => {
                        (e.currentTarget as HTMLElement).style.borderColor = completed
                          ? "rgba(110,231,183,0.40)"
                          : "rgba(167,139,250,0.30)";
                      }}
                      onMouseLeave={(e) => {
                        (e.currentTarget as HTMLElement).style.borderColor = completed
                          ? "rgba(110,231,183,0.20)"
                          : "rgba(155,159,196,0.15)";
                      }}
                    >
                      <div className="flex gap-3 p-3.5">
                        {/* 썸네일 */}
                        <div className="w-20 h-20 rounded-xl flex-shrink-0 relative overflow-hidden"
                          style={{
                            background: img
                              ? `url(${img}) center/cover`
                              : `radial-gradient(ellipse at 50% 30%, rgba(139,92,246,0.35), #1c1733)`,
                            border: completed
                              ? "1px solid rgba(110,231,183,0.30)"
                              : "1px solid rgba(155,159,196,0.20)",
                          }}>
                          {!img && (
                            <div className="w-full h-full flex items-center justify-center">
                              <Shield size={26} style={{ color: "#c4b5fd" }} />
                            </div>
                          )}
                          {/* 상태 배지 */}
                          <div className="absolute bottom-0 left-0 right-0 text-center text-[9px] font-bold py-0.5"
                            style={{
                              background: completed ? "rgba(110,231,183,0.30)" : "rgba(155,159,196,0.20)",
                              color: completed ? "#6ee7b7" : "rgba(196,181,253,0.65)",
                              backdropFilter: "blur(6px)",
                            }}>
                            {completed ? "✓ 완료" : "기록"}
                          </div>
                        </div>

                        {/* 정보 */}
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-1 mb-1.5 flex-wrap">
                            {r.difficulty && (
                              <span className="px-1.5 py-0.5 rounded text-[9px] font-bold"
                                style={{ background: "rgba(244,114,182,0.18)", color: "#f9a8d4" }}>
                                {r.difficulty}
                              </span>
                            )}
                            {r.experience && (
                              <span className="px-1.5 py-0.5 rounded text-[9px] font-bold"
                                style={{ background: "rgba(110,231,183,0.18)", color: "#6ee7b7" }}>
                                {r.experience}
                              </span>
                            )}
                            <span className="text-[9px] ml-auto flex items-center gap-1"
                              style={{ color: "rgba(155,159,196,0.5)" }}>
                              <Clock size={9} />
                              {r.raid_time}
                            </span>
                          </div>

                          <div className="text-sm font-bold text-white mb-1.5 truncate">
                            {r.raid_name || "이름 없음"}
                          </div>

                          {/* 공대장 */}
                          {r.leader_name && (
                            <div className="inline-flex items-center gap-1 px-2 py-0.5 rounded-md mb-2"
                              style={{ background: "rgba(251,191,36,0.10)", border: "1px solid rgba(251,191,36,0.20)" }}>
                              <Crown size={10} style={{ color: "#fbbf24" }} />
                              <span className="text-[10px] font-bold" style={{ color: "#fbbf24" }}>
                                공대장 · {r.leader_name}
                              </span>
                            </div>
                          )}

                          {/* 참여자 + 내 표시 */}
                          <div className="flex items-center gap-2 flex-wrap">
                            {parts.length > 0 ? (
                              <div className="flex">
                                {parts.slice(0, 5).map((p: any, i: number) => (
                                  <div
                                    key={i}
                                    className="w-6 h-6 rounded-md flex items-center justify-center text-[9px] font-bold"
                                    style={{
                                      background: "linear-gradient(135deg, #6d28d9, #4c1d95)",
                                      border: "1.5px solid #15122a",
                                      color: "#ede9fe",
                                      marginLeft: i === 0 ? 0 : -6,
                                      zIndex: 5 - i,
                                    }}
                                    title={`${p.character_name} (${p.class_name || ""})`}
                                  >
                                    {String(p.character_name || "?").slice(0, 1)}
                                  </div>
                                ))}
                                {parts.length > 5 && (
                                  <div
                                    className="w-6 h-6 rounded-md flex items-center justify-center text-[9px] font-bold"
                                    style={{
                                      background: "rgba(139,92,246,0.18)",
                                      border: "1.5px solid #15122a",
                                      color: "#c4b5fd",
                                      marginLeft: -6,
                                    }}
                                  >
                                    +{parts.length - 5}
                                  </div>
                                )}
                              </div>
                            ) : (
                              <span className="text-[10px]" style={{ color: "rgba(155,159,196,0.5)" }}>
                                참여자 정보 없음
                              </span>
                            )}
                            <span className="text-[10px]" style={{ color: "rgba(155,159,196,0.6)" }}>
                              {parts.length}명 참여
                            </span>
                            {myParticipation && (
                              <span className="px-1.5 py-0.5 rounded-md text-[9px] font-bold"
                                style={{ background: "rgba(139,92,246,0.20)", color: "#c4b5fd", border: "1px solid rgba(139,92,246,0.30)" }}>
                                내가 참여
                              </span>
                            )}
                          </div>
                        </div>
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* 상세 모달 */}
      {detailRaid && (
        <RaidHistoryDetailModal
          raid={detailRaid}
          participants={participantsMap[String(detailRaid.id)] || []}
          contentImg={contentImgMap[String(detailRaid.raid_name || "").trim()]}
          profile={profile}
          onClose={() => setDetailRaid(null)}
        />
      )}
    </div>
  );
};


// ✅ ─────────────────────────────────────────────────────────
// 출석 체크 시스템
// ─────────────────────────────────────────────────────────────
const ATTENDANCE_REWARDS = {
  base: 10,        // 매일 출석 기본 보상
  bonus_7day: 10,  // 7일 연속 출석 보너스
};

const calcAttendanceReward = (streak: number) => {
  let points = ATTENDANCE_REWARDS.base;
  const bonuses: string[] = [];
  if (streak > 0 && streak % 7 === 0) {
    points += ATTENDANCE_REWARDS.bonus_7day;
    bonuses.push(`7일 연속 보너스 +${ATTENDANCE_REWARDS.bonus_7day}P`);
  }
  return { points, bonuses };
};

const dateToKey = (d: Date) => {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
};
const todayKey = () => dateToKey(new Date());
const yesterdayKey = () => {
  const d = new Date();
  d.setDate(d.getDate() - 1);
  return dateToKey(d);
};

// 사이드바에 들어가는 컴팩트 위젯
const AttendanceWidget = ({ user, onOpenModal, refreshKey }: any) => {
  const [todayAttended, setTodayAttended] = useState(false);
  const [streak, setStreak] = useState(0);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!user?.id) { setLoading(false); return; }
    let mounted = true;
    (async () => {
      setLoading(true);
      const { data, error } = await supabase
        .from("attendance")
        .select("attended_date, streak_days")
        .eq("user_id", user.id)
        .order("attended_date", { ascending: false })
        .limit(1)
        .maybeSingle();
      if (!mounted) return;
      if (!error && data) {
        const today = todayKey();
        const isToday = data.attended_date === today;
        const isYesterday = data.attended_date === yesterdayKey();
        setTodayAttended(isToday);
        setStreak(isToday || isYesterday ? (data.streak_days || 0) : 0);
      } else {
        setTodayAttended(false);
        setStreak(0);
      }
      setLoading(false);
    })();
    return () => { mounted = false; };
  }, [user?.id, refreshKey]);

  if (!user) return null;

  return (
    <button
      onClick={onOpenModal}
      className={cn(
        "mx-3 mb-2 px-3 py-2.5 rounded-xl border transition-all text-left flex items-center gap-2.5",
        todayAttended
          ? "border-emerald-400/25 bg-emerald-500/[0.06] hover:bg-emerald-500/10"
          : "border-amber-400/30 bg-amber-500/[0.08] hover:bg-amber-500/15"
      )}
      style={!todayAttended && !loading ? { animation: "pulse 2.5s ease-in-out infinite" } : {}}
    >
      <div className="text-base flex-shrink-0">
        {loading ? "⏳" : todayAttended ? "✅" : "📅"}
      </div>
      <div className="flex-1 min-w-0">
        <div className={cn(
          "text-[11px] font-bold truncate",
          todayAttended ? "text-emerald-300" : "text-amber-200"
        )}>
          {loading ? "확인 중..." : todayAttended ? "오늘 출석 완료" : "오늘 출석체크 +10P"}
        </div>
        <div className="text-[9px] text-stone-400 truncate">
          {streak > 0 ? `🔥 ${streak}일 연속 · 클릭` : "클릭하여 캘린더 보기"}
        </div>
      </div>
    </button>
  );
};

// 미니 캘린더 (월별 출석 표시)
const MiniCalendar = ({ year, month, attendedDates, onMonthChange, allowNav = true, compact = false }: any) => {
  const firstDay = new Date(year, month, 1);
  const lastDay = new Date(year, month + 1, 0);
  const startWeekday = firstDay.getDay();
  const daysInMonth = lastDay.getDate();
  const today = new Date();
  const isCurrentMonth = today.getFullYear() === year && today.getMonth() === month;
  const todayDate = today.getDate();
  const attendedSet = new Set(attendedDates || []);

  const cells: Array<{ day: number | null; isToday: boolean; isAttended: boolean }> = [];
  for (let i = 0; i < startWeekday; i++) cells.push({ day: null, isToday: false, isAttended: false });
  for (let d = 1; d <= daysInMonth; d++) {
    const dateStr = `${year}-${String(month + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
    cells.push({
      day: d,
      isToday: isCurrentMonth && d === todayDate,
      isAttended: attendedSet.has(dateStr),
    });
  }

  return (
    <div className={cn("bg-black/30 rounded-xl border border-white/10", compact ? "p-2" : "p-3")}>
      {allowNav ? (
        <div className="flex items-center justify-between mb-2">
          <button onClick={() => onMonthChange?.(-1)} className="p-1 rounded hover:bg-white/10 text-stone-400">
            <ChevronLeft size={14} />
          </button>
          <div className="text-xs font-bold text-white">{year}년 {month + 1}월</div>
          <button onClick={() => onMonthChange?.(1)} className="p-1 rounded hover:bg-white/10 text-stone-400">
            <ChevronRight size={14} />
          </button>
        </div>
      ) : (
        !compact && <div className="text-xs font-bold text-white text-center mb-2">{year}년 {month + 1}월</div>
      )}

      <div className="grid grid-cols-7 gap-1 mb-1">
        {["일", "월", "화", "수", "목", "금", "토"].map((d, i) => (
          <div key={i} className={cn(
            "text-[9px] font-semibold text-center py-0.5",
            i === 0 ? "text-red-400/70" : i === 6 ? "text-blue-400/70" : "text-stone-500"
          )}>{d}</div>
        ))}
      </div>

      <div className="grid grid-cols-7 gap-1">
        {cells.map((cell, i) => (
          <div
            key={i}
            className={cn(
              "aspect-square flex items-center justify-center text-[10px] font-medium rounded-md relative",
              cell.day === null && "invisible",
              cell.day !== null && !cell.isAttended && "text-stone-600",
              cell.isAttended && "bg-amber-500/25 text-amber-100 border border-amber-400/40",
              cell.isToday && !cell.isAttended && "border border-emerald-400/40 text-emerald-300",
              cell.isToday && cell.isAttended && "ring-1 ring-emerald-400/60"
            )}
          >
            {cell.day}
          </div>
        ))}
      </div>
    </div>
  );
};

// 출석 모달 (내 출석 + 전체 길드원 2개 탭)
const AttendanceModal = ({ user, profile, open, onClose, onAttendanceChange }: any) => {
  const [tab, setTab] = useState<"me" | "guild">("me");
  const [myAttendance, setMyAttendance] = useState<any[]>([]);
  const [guildList, setGuildList] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [calYear, setCalYear] = useState(new Date().getFullYear());
  const [calMonth, setCalMonth] = useState(new Date().getMonth());
  const [expandedUserId, setExpandedUserId] = useState<string | null>(null);

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") onClose?.(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open, onClose]);

  const fetchMyAttendance = async () => {
    if (!user?.id) return;
    setLoading(true);
    const { data, error } = await supabase
      .from("attendance")
      .select("attended_date, streak_days, points_earned")
      .eq("user_id", user.id)
      .order("attended_date", { ascending: false });
    if (!error) setMyAttendance(data || []);
    setLoading(false);
  };

  const fetchGuildAttendance = async () => {
    if (!supabase) return;
    setLoading(true);
    const startDate = `${calYear}-${String(calMonth + 1).padStart(2, "0")}-01`;
    const lastDay = new Date(calYear, calMonth + 1, 0).getDate();
    const endDate = `${calYear}-${String(calMonth + 1).padStart(2, "0")}-${String(lastDay).padStart(2, "0")}`;

    const [profilesRes, monthAttendRes, latestRes] = await Promise.all([
      supabase.from("profiles").select("id, nickname, character_name, role"),
      supabase.from("attendance").select("user_id, attended_date").gte("attended_date", startDate).lte("attended_date", endDate),
      supabase.from("attendance").select("user_id, streak_days, attended_date").order("attended_date", { ascending: false }),
    ]);

    const profiles = profilesRes.data || [];
    const monthData = monthAttendRes.data || [];
    const latestData = latestRes.data || [];

    const grouped: Record<string, string[]> = {};
    monthData.forEach((a: any) => {
      if (!grouped[a.user_id]) grouped[a.user_id] = [];
      grouped[a.user_id].push(a.attended_date);
    });

    const latestMap: Record<string, { streak: number; date: string }> = {};
    latestData.forEach((row: any) => {
      if (!latestMap[row.user_id]) {
        latestMap[row.user_id] = { streak: row.streak_days || 0, date: row.attended_date };
      }
    });

    const today = todayKey();
    const yesterday = yesterdayKey();
    const result = profiles.map((p: any) => {
      const dates = grouped[p.id] || [];
      const latest = latestMap[p.id];
      const currentStreak = latest && (latest.date === today || latest.date === yesterday) ? latest.streak : 0;
      return {
        ...p,
        attendedDates: dates,
        attendedCount: dates.length,
        currentStreak,
      };
    }).sort((a: any, b: any) => {
      if (b.attendedCount !== a.attendedCount) return b.attendedCount - a.attendedCount;
      return b.currentStreak - a.currentStreak;
    });

    setGuildList(result);
    setLoading(false);
  };

  useEffect(() => {
    if (!open) return;
    if (tab === "me") fetchMyAttendance();
    else fetchGuildAttendance();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, tab, calYear, calMonth]);

  const handleCheckIn = async () => {
    if (!user?.id || submitting) return;
    const today = todayKey();
    if (myAttendance.some((a) => a.attended_date === today)) {
      showToast("이미 오늘 출석했습니다.", "info");
      return;
    }
    setSubmitting(true);
    try {
      const yKey = yesterdayKey();
      const yesterdayRecord = myAttendance.find((a) => a.attended_date === yKey);
      const newStreak = yesterdayRecord ? (yesterdayRecord.streak_days || 0) + 1 : 1;
      const { points, bonuses } = calcAttendanceReward(newStreak);

      const { error: insertErr } = await supabase.from("attendance").insert({
        user_id: user.id,
        attended_date: today,
        streak_days: newStreak,
        points_earned: points,
      });

      if (!insertErr) {
        // 🏆 출석 → 업적 자동 평가
        triggerAchievementEval(user?.id);
      }

      if (insertErr) {
        const msg = insertErr.message || "";
        if (msg.includes("duplicate") || msg.includes("unique")) {
          showToast("이미 출석한 날입니다.", "info");
        } else if (msg.toLowerCase().includes("does not exist") || msg.toLowerCase().includes("relation")) {
          showToast("attendance 테이블이 없습니다. 아래 SQL을 먼저 실행해주세요.", "error");
        } else {
          showToast(`출석 실패: ${msg}`, "error");
        }
        console.error(insertErr);
        setSubmitting(false);
        return;
      }

      // 포인트 적립
      const { data: profileRow } = await supabase.from("profiles").select("points").eq("id", user.id).maybeSingle();
      const currentPoints = profileRow?.points || 0;
      await supabase.from("profiles").update({ points: currentPoints + points }).eq("id", user.id);

      // 포인트 로그 (있으면 기록, 실패해도 무시)
      try {
        await supabase.from("point_earn_logs").insert({
          user_id: user.id,
          points,
          reason: `출석 체크 (${newStreak}일 연속)`,
          source: "attendance",
        });
      } catch { /* point_earn_logs 스키마가 다를 수 있으므로 무시 */ }

      const bonusText = bonuses.length > 0 ? ` 🎉 ${bonuses.join(", ")}` : "";
      showToast(`출석 완료! +${points}P · 🔥 ${newStreak}일 연속${bonusText}`, "success");

      fetchMyAttendance();
      onAttendanceChange?.();
    } catch (e: any) {
      showToast(`오류: ${e.message || e}`, "error");
      console.error(e);
    }
    setSubmitting(false);
  };

  if (!open) return null;

  const today = todayKey();
  const todayAttended = myAttendance.some((a) => a.attended_date === today);
  const latest = myAttendance[0];
  const currentStreak = latest && (latest.attended_date === today || latest.attended_date === yesterdayKey())
    ? (latest.streak_days || 0)
    : 0;

  const thisMonthCount = myAttendance.filter((a) => {
    const [y, m] = a.attended_date.split("-");
    return parseInt(y) === calYear && parseInt(m) === calMonth + 1;
  }).length;

  const totalPoints = myAttendance.reduce((sum, a) => sum + (a.points_earned || 0), 0);
  const myAttendedDates = myAttendance.map((a) => a.attended_date);

  return (
    <div
      className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm"
      onClick={onClose}
    >
      <div
        className="relative w-full max-w-2xl max-h-[90vh] overflow-y-auto rounded-2xl border border-white/10 bg-[#0d0d14] p-6"
        onClick={(e) => e.stopPropagation()}
      >
        {/* 헤더 */}
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-2xl bg-amber-400/15 border border-amber-400/20">
              <CalendarDays size={20} className="text-amber-300" />
            </div>
            <div>
              <div className="text-[10px] font-semibold uppercase tracking-[0.3em] text-amber-300/70">Attendance</div>
              <div className="text-lg font-bold text-white">출석 체크</div>
            </div>
          </div>
          <button onClick={onClose} className="p-2 rounded-lg hover:bg-white/10 text-stone-400">
            <X size={18} />
          </button>
        </div>

        {/* 탭 */}
        <div className="flex gap-1 mb-5 border-b border-white/10">
          <button
            onClick={() => setTab("me")}
            className={cn(
              "px-4 py-2.5 text-sm font-semibold transition-all",
              tab === "me" ? "text-amber-300 border-b-2 border-amber-400" : "text-stone-500 hover:text-stone-300"
            )}
          >
            내 출석
          </button>
          <button
            onClick={() => setTab("guild")}
            className={cn(
              "px-4 py-2.5 text-sm font-semibold transition-all",
              tab === "guild" ? "text-amber-300 border-b-2 border-amber-400" : "text-stone-500 hover:text-stone-300"
            )}
          >
            전체 길드원
          </button>
        </div>

        {/* === 내 출석 === */}
        {tab === "me" && (
          <div className="space-y-4">
            <div className="grid grid-cols-3 gap-2">
              <div className="rounded-xl border border-amber-400/20 bg-amber-500/[0.04] p-3 text-center">
                <div className="text-[10px] text-stone-400 mb-1">🔥 연속 출석</div>
                <div className="text-xl font-bold text-amber-300">{currentStreak}일</div>
              </div>
              <div className="rounded-xl border border-white/10 bg-white/[0.03] p-3 text-center">
                <div className="text-[10px] text-stone-400 mb-1">📅 이번 달</div>
                <div className="text-xl font-bold text-white">{thisMonthCount}일</div>
              </div>
              <div className="rounded-xl border border-emerald-400/20 bg-emerald-500/[0.04] p-3 text-center">
                <div className="text-[10px] text-stone-400 mb-1">💰 누적 P</div>
                <div className="text-xl font-bold text-emerald-300">{totalPoints}</div>
              </div>
            </div>

            <button
              onClick={handleCheckIn}
              disabled={submitting || todayAttended}
              className={cn(
                "w-full py-3.5 rounded-xl font-bold text-sm transition-all",
                todayAttended
                  ? "bg-emerald-500/10 border border-emerald-400/30 text-emerald-300 cursor-not-allowed"
                  : "bg-gradient-to-r from-amber-500 to-orange-500 text-black hover:from-amber-400 hover:to-orange-400 shadow-lg shadow-amber-500/20"
              )}
            >
              {submitting ? "처리 중..." : todayAttended ? "✅ 오늘 출석 완료!" : "📅 오늘 출석체크 받기 (+10P)"}
            </button>

            <MiniCalendar
              year={calYear}
              month={calMonth}
              attendedDates={myAttendedDates}
              onMonthChange={(delta: number) => {
                const nd = new Date(calYear, calMonth + delta, 1);
                setCalYear(nd.getFullYear());
                setCalMonth(nd.getMonth());
              }}
              allowNav
            />

            <div className="rounded-xl border border-white/10 bg-white/[0.02] p-3 text-[11px] text-stone-400 space-y-1">
              <div className="font-bold text-amber-300 mb-1.5">💎 출석 보상</div>
              <div>• 매일 출석: <span className="text-amber-200">+10P</span></div>
              <div>• 7일 연속 출석: <span className="text-amber-200">+10P 보너스</span> (총 20P)</div>
              <div className="text-stone-500 mt-1.5">⚠️ 하루라도 빠지면 연속 카운트가 1일부터 다시 시작합니다.</div>
            </div>
          </div>
        )}

        {/* === 전체 길드원 === */}
        {tab === "guild" && (
          <div className="space-y-3">
            <div className="flex items-center justify-between bg-black/30 rounded-xl border border-white/10 px-4 py-2.5">
              <button
                onClick={() => {
                  const nd = new Date(calYear, calMonth - 1, 1);
                  setCalYear(nd.getFullYear()); setCalMonth(nd.getMonth());
                  setExpandedUserId(null);
                }}
                className="p-1 rounded hover:bg-white/10 text-stone-400"
              ><ChevronLeft size={16} /></button>
              <div className="text-sm font-bold text-white">{calYear}년 {calMonth + 1}월</div>
              <button
                onClick={() => {
                  const nd = new Date(calYear, calMonth + 1, 1);
                  setCalYear(nd.getFullYear()); setCalMonth(nd.getMonth());
                  setExpandedUserId(null);
                }}
                className="p-1 rounded hover:bg-white/10 text-stone-400"
              ><ChevronRight size={16} /></button>
            </div>

            {loading ? (
              <div className="text-center py-12 text-stone-500 text-sm">불러오는 중...</div>
            ) : guildList.length === 0 ? (
              <div className="text-center py-12 text-stone-500 text-sm">길드원이 없습니다.</div>
            ) : (
              <div className="space-y-2">
                {guildList.map((m: any, idx: number) => {
                  const daysInMonth = new Date(calYear, calMonth + 1, 0).getDate();
                  const today2 = new Date();
                  const isCurMonth = today2.getFullYear() === calYear && today2.getMonth() === calMonth;
                  const elapsedDays = isCurMonth ? today2.getDate() : daysInMonth;
                  const rate = elapsedDays > 0 ? Math.round((m.attendedCount / elapsedDays) * 100) : 0;
                  const isExpanded = expandedUserId === m.id;
                  const isMe = m.id === user?.id;

                  return (
                    <div key={m.id} className="rounded-xl border border-white/10 bg-black/30">
                      <button
                        onClick={() => setExpandedUserId(isExpanded ? null : m.id)}
                        className="w-full p-3 flex items-center gap-3 hover:bg-white/[0.03] transition-all"
                      >
                        <div className={cn(
                          "w-7 h-7 rounded-lg flex items-center justify-center text-xs font-bold flex-shrink-0",
                          idx === 0 ? "bg-amber-500/20" :
                          idx === 1 ? "bg-stone-400/20" :
                          idx === 2 ? "bg-orange-700/20" :
                          "bg-white/5 text-stone-500"
                        )}>
                          {idx === 0 ? "🥇" : idx === 1 ? "🥈" : idx === 2 ? "🥉" : idx + 1}
                        </div>
                        <div className="text-base flex-shrink-0">
                          {m.role === "admin" ? "👑" : m.role === "submaster" ? "⚔️" : "👤"}
                        </div>
                        <div className="flex-1 min-w-0 text-left">
                          <div className="flex items-center gap-2 flex-wrap">
                            <span className="text-sm font-bold text-white truncate">
                              {m.nickname || "(닉네임 없음)"}
                            </span>
                            {isMe && <span className="text-[9px] px-1 py-0.5 rounded bg-emerald-500/15 text-emerald-300 border border-emerald-400/20">본인</span>}
                            {(() => {
                              const todayStr = new Date().toISOString().slice(0, 10);
                              const attendedToday = m.attendedDates?.includes(todayStr);
                              return attendedToday
                                ? <span className="text-[9px] px-1.5 py-0.5 rounded-full bg-amber-500/15 text-amber-300 border border-amber-400/25">✅ 오늘 출석</span>
                                : <span className="text-[9px] px-1.5 py-0.5 rounded-full bg-white/5 text-stone-500 border border-white/8">미출석</span>;
                            })()}
                            {m.currentStreak > 0 && (
                              <span className="text-[10px] text-amber-300">🔥 {m.currentStreak}일</span>
                            )}
                          </div>
                          <div className="flex items-center gap-2 mt-1">
                            <div className="flex-1 h-1.5 bg-white/5 rounded-full overflow-hidden">
                              <div
                                className="h-full bg-gradient-to-r from-amber-500 to-orange-500 transition-all"
                                style={{ width: `${Math.min(100, rate)}%` }}
                              />
                            </div>
                            <span className="text-[10px] text-stone-400 flex-shrink-0 tabular-nums">
                              {m.attendedCount}/{elapsedDays}일 ({rate}%)
                            </span>
                          </div>
                        </div>
                        <ChevronDown
                          size={14}
                          className={cn(
                            "text-stone-500 transition-transform flex-shrink-0",
                            isExpanded && "rotate-180"
                          )}
                        />
                      </button>
                      {isExpanded && (
                        <div className="px-3 pb-3">
                          <MiniCalendar
                            year={calYear}
                            month={calMonth}
                            attendedDates={m.attendedDates}
                            allowNav={false}
                          />
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};


