const RaidContentEditor = ({ isRaid }: { isRaid: boolean }) => {
  const [list, setList] = useState<any[]>([]);
  const [selectedGate, setSelectedGate] = useState(1);
  const [difficulty, setDifficulty] = useState("노말");
  const [editingId, setEditingId] = useState<string | null>(null);
  // 커스텀 배틀아이템 관리
  // ── 배틀아이템 — Supabase DB 기반 ──
  const [customBattleItems, setCustomBattleItems] = useState<Array<{id?:string;name:string;icon:string;image_url:string}>>([]);
  const [newBattleItem, setNewBattleItem] = useState({ name:"", icon:"🎒", image_url:"" });
  const [showAddBattleItem, setShowAddBattleItem] = useState(false);
  const [uploadingBattleIcon, setUploadingBattleIcon] = useState(false);
  const [uploadingRewardImg, setUploadingRewardImg] = useState(false);
  const [savingBattleItem, setSavingBattleItem] = useState(false);

  // 커스텀 배틀아이템 DB 로드
  useEffect(() => {
    const load = async () => {
      try {
        const { data } = await supabase.from("battle_items").select("*").order("created_at");
        setCustomBattleItems(data || []);
      } catch {}
    };
    load();
  }, []);
  const [form, setForm] = useState<any>({
    name: "",
    image_url: "",
    hp: "",
    element: "",
    attribute: "",
    gold: 0,
    more_gold: 0,
    battle_items: "",
    guide: "",
    mechanics: "",
    tip: "",
    reward_image_url: "",
    raid_skill_1_image: "",
    raid_skill_1_name: "",
    raid_skill_1_desc: "",
    raid_skill_2_image: "",
    raid_skill_2_name: "",
    raid_skill_2_desc: "",
    raid_skill_3_image: "",
    raid_skill_3_name: "",
    raid_skill_3_desc: "",
  });

  const elementOptions = ["악마형", "야수형", "인간형", "정령형", "기계형", "고대", "불사", "신"];
  const attributeOptions = ["화속성 취약", "수속성 취약", "암속성 취약", "빛속성 취약", "토속성 취약", "뇌속성 취약"];

  // 기본 배틀아이템 + 커스텀 합산
  const defaultBattleItems = [
    { name:"홀리 워터", icon:"💊", image_url:"" },
    { name:"고급 폭탄", icon:"💣", image_url:"" },
    { name:"정밀 폭탄", icon:"🎯", image_url:"" },
    { name:"시간의 모래", icon:"⏳", image_url:"" },
    { name:"상급 회복 물약", icon:"🧪", image_url:"" },
    { name:"고급 수류탄", icon:"💥", image_url:"" },
    { name:"각성 포션", icon:"✨", image_url:"" },
    { name:"흑마법 폭탄", icon:"🖤", image_url:"" },
    { name:"화염 수류탄", icon:"🔥", image_url:"" },
    { name:"독 폭탄", icon:"☠️", image_url:"" },
    { name:"섬광 수류탄", icon:"💡", image_url:"" },
  ];
  const allBattleItemDefs = [...defaultBattleItems, ...customBattleItems];

  const saveCustomBattleItem = async (item: {name:string;icon:string;image_url:string}) => {
    setSavingBattleItem(true);
    try {
      const { data, error } = await supabase.from("battle_items").insert(item).select().single();
      if (error) throw error;
      setCustomBattleItems(p => [...p, data]);
      showToast("배틀아이템 추가 완료!", "success");
    } catch (e: any) {
      showToast("저장 실패: " + (e.message || "오류"), "error");
    }
    setSavingBattleItem(false);
  };

  const deleteCustomBattleItem = async (id: string, name: string) => {
    try {
      await supabase.from("battle_items").delete().eq("id", id);
      setCustomBattleItems(p => p.filter(c => c.id !== id));
      // 선택된 배틀아이템에서도 제거
      const current = (form.battle_items || "").split(",").map((s:string)=>s.trim()).filter(Boolean);
      if (current.includes(name)) {
        setForm((p: any) => ({ ...p, battle_items: current.filter((v:string)=>v!==name).join(", ") }));
      }
      showToast("삭제 완료", "success");
    } catch (e: any) { showToast("삭제 실패: " + e.message, "error"); }
  };

  const uploadBattleIcon = async (file: File) => {
    setUploadingBattleIcon(true);
    try {
      const client = getSupabaseOrThrow();
      const ext = file.name.split(".").pop();
      const path = `battle_items/${Date.now()}.${ext}`;
      const { error } = await client.storage.from("images").upload(path, file, { upsert: true });
      if (error) throw error;
      const { data: { publicUrl } } = client.storage.from("images").getPublicUrl(path);
      setNewBattleItem(p => ({ ...p, image_url: publicUrl }));
    } catch (e: any) { showToast("아이콘 업로드 실패: " + e.message, "error"); }
    setUploadingBattleIcon(false);
  };

  const uploadRewardImage = async (file: File) => {
    setUploadingRewardImg(true);
    try {
      const client = getSupabaseOrThrow();
      const ext = file.name.split(".").pop();
      const path = `reward_images/${Date.now()}.${ext}`;
      const { error } = await client.storage.from("images").upload(path, file, { upsert: true });
      if (error) throw error;
      const { data: { publicUrl } } = client.storage.from("images").getPublicUrl(path);
      setForm((p: any) => ({ ...p, reward_image_url: publicUrl }));
    } catch (e: any) { showToast("이미지 업로드 실패: " + e.message, "error"); }
    setUploadingRewardImg(false);
  };

  const uploadRaidSkillImage = async (file: File, skillNum: 1 | 2 | 3) => {
    try {
      const client = getSupabaseOrThrow();
      const ext = file.name.split(".").pop();
      const path = `raid_skills/${Date.now()}_${skillNum}.${ext}`;
      const { error } = await client.storage.from("images").upload(path, file, { upsert: true });
      if (error) throw error;
      const { data: { publicUrl } } = client.storage.from("images").getPublicUrl(path);
      setForm((p: any) => ({ ...p, [`raid_skill_${skillNum}_image`]: publicUrl }));
      showToast(`스킬 ${skillNum} 이미지 업로드 완료!`, "success");
    } catch (e: any) { showToast("이미지 업로드 실패: " + e.message, "error"); }
  };

  useEffect(() => {
    fetchList();
  }, [isRaid]);

  useEffect(() => {
    if (!editingId) return;
    const currentItem = list.find((item: any) => item.id === editingId);
    if (currentItem) {
      void loadItem(currentItem, false);
    }
  }, [editingId, difficulty, selectedGate, list]);

  const fetchList = async () => {
    const { data, error } = await supabase
      .from("contents")
      .select("*")
      .eq("category", isRaid ? "레이드" : "가디언 토벌")
      .order("name");

    if (error) {
      console.error(error);
      setList([]);
      return;
    }

    setList(data || []);
  };

  const createBaseForm = (item?: any) => ({
    name: item?.name || "",
    image_url: item?.image_url || "",
    hp: "",
    element: "",
    attribute: "",
    gold: 0,
    more_gold: 0,
    battle_items: "",
    guide: "",
    mechanics: "",
    tip: "",
    reward_image_url: "",
    raid_skill_1_image: "",
    raid_skill_1_name: "",
    raid_skill_1_desc: "",
    raid_skill_2_image: "",
    raid_skill_2_name: "",
    raid_skill_2_desc: "",
    raid_skill_3_image: "",
    raid_skill_3_name: "",
    raid_skill_3_desc: "",
  });

  const normalizeRewardText = (value: any) => {
    if (!value) return "";
    if (Array.isArray(value)) {
      return value
        .map((item) => {
          if (typeof item === "string") return item;
          const name = String(item?.name || item?.item || item?.title || item?.material || "").trim();
          const quantity = String(item?.quantity || item?.count || "").trim();
          return quantity ? `${name} x${quantity}` : name;
        })
        .filter(Boolean)
        .join("\n");
    }
    if (typeof value === "string") return value;
    try {
      return JSON.stringify(value, null, 2);
    } catch {
      return "";
    }
  };

  const loadItem = async (item: any, activateEdit = true) => {
    if (activateEdit) setEditingId(item.id);

    const baseForm = createBaseForm(item);

    let query = supabase.from("content_details").select("*").eq("content_id", item.id);

    if (isRaid) {
      query = query.eq("difficulty", difficulty).eq("gate_num", selectedGate);
    } else {
      query = query.eq("gate_num", 0);
    }

    const data = await safeSingle(query);

    setForm({
      ...baseForm,
      hp: data?.hp || "",
      element: data?.element_type || "",
      attribute: data?.attribute || "",
      gold: data?.clear_gold || 0,
      more_gold: data?.more_gold || 0,
      battle_items: data?.battle_items || "",
      guide: data?.guide || data?.description || data?.desc || data?.memo || data?.note || "",
      mechanics: data?.mechanics || data?.pattern || data?.patterns || data?.mechanic || "",
      tip: data?.tip || data?.tips || data?.recommendation || data?.recommend || data?.comment || "",
      reward_image_url: data?.reward_image_url || "",
      raid_skill_1_image: data?.raid_skill_1_image || "",
      raid_skill_1_name:  data?.raid_skill_1_name  || "",
      raid_skill_1_desc:  data?.raid_skill_1_desc  || "",
      raid_skill_2_image: data?.raid_skill_2_image || "",
      raid_skill_2_name:  data?.raid_skill_2_name  || "",
      raid_skill_2_desc:  data?.raid_skill_2_desc  || "",
      raid_skill_3_image: data?.raid_skill_3_image || "",
      raid_skill_3_name:  data?.raid_skill_3_name  || "",
      raid_skill_3_desc:  data?.raid_skill_3_desc  || "",
    });
  };

  const resetForm = () => {
    setEditingId(null);
    setSelectedGate(1);
    setDifficulty("노말");
    setForm(createBaseForm());
  };

  const handleSave = async () => {
    if (!form.name) return showToast("이름을 입력하세요.");

    const { data, error: cErr } = await supabase
      .from("contents")
      .upsert(
        {
          id: editingId || undefined,
          name: form.name,
          category: isRaid ? "레이드" : "가디언 토벌",
          image_url: form.image_url,
        },
        { onConflict: "id" },
      )
      .select()
      .single();

    if (cErr) return showToast(cErr.message, "error");

    // ── 기존 row 조회 후 insert / update 분리 (onConflict unique constraint 불필요)
    const diffVal    = isRaid ? difficulty : null;
    const gateVal    = isRaid ? Number(selectedGate) : 0;

    let existQuery = supabase
      .from("content_details")
      .select("id")
      .eq("content_id", data.id)
      .eq("gate_num", gateVal);

    if (diffVal !== null) {
      existQuery = existQuery.eq("difficulty", diffVal);
    } else {
      existQuery = existQuery.is("difficulty", null);
    }

    const { data: existRow } = await existQuery.maybeSingle();

    // 전체 필드 payload
    // DB 컬럼 기준 payload
    const detailPayload: Record<string, any> = {
      content_id:       data.id,
      difficulty:       diffVal,
      gate_num:         gateVal,
      hp:               form.hp || null,
      element_type:     form.element || null,
      attribute:        form.attribute || null,
      clear_gold:       Number(form.gold) || 0,
      more_gold:        Number(form.more_gold) || 0,
      battle_items:     form.battle_items || null,
      guide:            form.guide || null,
      mechanics:        form.mechanics || null,
      tip:              form.tip || null,
      reward_image_url:   form.reward_image_url || null,
      raid_skill_1_image: form.raid_skill_1_image || null,
      raid_skill_1_name:  form.raid_skill_1_name  || null,
      raid_skill_1_desc:  form.raid_skill_1_desc  || null,
      raid_skill_2_image: form.raid_skill_2_image || null,
      raid_skill_2_name:  form.raid_skill_2_name  || null,
      raid_skill_2_desc:  form.raid_skill_2_desc  || null,
      raid_skill_3_image: form.raid_skill_3_image || null,
      raid_skill_3_name:  form.raid_skill_3_name  || null,
      raid_skill_3_desc:  form.raid_skill_3_desc  || null,
    };

    let dErr: any = null;

    if (existRow?.id) {
      // UPDATE
      const { error } = await supabase
        .from("content_details")
        .update(detailPayload)
        .eq("id", existRow.id);
      dErr = error;
    } else {
      // INSERT
      const { error } = await supabase
        .from("content_details")
        .insert(detailPayload);
      dErr = error;
    }

    // 컬럼 없음 오류 → reward_image_url 제외하고 재시도
    if (dErr && (String(dErr.message || "").includes("column") || String(dErr.message || "").includes("does not exist"))) {
      // reward_image_url 없는 경우를 위한 fallback
      const { reward_image_url, ...payloadWithout } = detailPayload;
      let retryErr: any = null;
      if (existRow?.id) {
        const { error } = await supabase.from("content_details").update(payloadWithout).eq("id", existRow.id);
        retryErr = error;
      } else {
        const { error } = await supabase.from("content_details").insert(payloadWithout);
        retryErr = error;
      }
      dErr = retryErr;
      if (!retryErr) {
        showToast("저장 완료! (reward_image_url 컬럼이 없어 이미지는 미저장)", "info");
        await fetchList();
        resetForm();
        return;
      }
    }

    if (dErr) {
      showToast("저장 실패: " + (dErr.message || JSON.stringify(dErr)), "error");
      return;
    }

    showToast(editingId ? "수정 완료!" : "등록 완료!", "success");
    await fetchList();
    resetForm();
  };

  const deleteItem = async (id: string, name: string) => {
    if (!confirm(`[${name}]을(를) 삭제하시겠습니까?`)) return;
    await supabase.from("content_details").delete().eq("content_id", id);
    const { error } = await supabase.from("contents").delete().eq("id", id);
    if (!error) {
      showToast("삭제 완료", "success");
      fetchList();
      resetForm();
    }
  };

  return (
    <div className="grid gap-8 xl:grid-cols-[0.78fr,1.22fr]">
      <div className="space-y-5">
        <AdminSectionCard
          title="Content Library"
          description={`${isRaid ? "레이드" : "가디언 토벌"} 콘텐츠를 선택하면 우측에서 상세 데이터를 편집할 수 있어.`}
        >
          <div className="max-h-[620px] space-y-2 overflow-y-auto pr-1">
            {list.map((item) => (
              <button
                key={item.id}
                onClick={() => loadItem(item)}
                className={cn(
                  "flex w-full items-center justify-between rounded-[1.35rem] border px-4 py-4 text-left transition-all",
                  editingId === item.id
                    ? "border-amber-200/22 bg-amber-300/[0.08] shadow-[0_16px_36px_rgba(180,138,61,0.12)]"
                    : "border-white/10 bg-white/[0.03] hover:border-white/20 hover:bg-white/[0.05]"
                )}
              >
                <div className="min-w-0">
                  <div className="truncate text-sm font-semibold text-white">{item.name}</div>
                  <div className="mt-1 text-xs text-slate-500">
                    {editingId === item.id ? "현재 편집 중" : "클릭하여 상세 편집"}
                  </div>
                </div>
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    deleteItem(item.id, item.name);
                  }}
                  className="ml-4 shrink-0 text-slate-600 transition-colors hover:text-red-400"
                >
                  <Trash2 size={16} />
                </button>
              </button>
            ))}
          </div>
        </AdminSectionCard>
      </div>

      <div className="space-y-5">
        {editingId && (
          <div className="rounded-[1.35rem] border border-yellow-400/20 bg-yellow-400/10 px-4 py-3 text-xs font-semibold uppercase tracking-[0.22em] text-yellow-200">
            수정 모드 활성화
          </div>
        )}

        <AdminSectionCard
          title="기본 정보"
          description="콘텐츠 이름과 대표 이미지를 관리해. 공통 메타 영역이야."
        >
          <div className="grid gap-4 md:grid-cols-[1fr,0.9fr]">
            <AdminInput
              label="Content Name"
              value={form.name}
              onChange={(v: any) => setForm({ ...form, name: v })}
            />
            <div className="rounded-[1.35rem] border border-white/10 bg-black/20 p-4">
              <ImageUploader
                label="Image"
                onUpload={(url) => setForm({ ...form, image_url: url })}
              />
              {form.image_url && (
                <img
                  src={form.image_url}
                  className="mt-4 h-36 w-full rounded-2xl object-cover"
                />
              )}
            </div>
          </div>
        </AdminSectionCard>

        {isRaid && (
          <AdminSectionCard
            title="관문 / 난이도 편집 위치"
            description="현재 편집할 관문과 난이도를 먼저 선택해. 선택 변경 시 해당 위치의 저장 데이터가 즉시 로드돼."
          >
            <div className="grid gap-4 lg:grid-cols-[1fr,1fr,0.9fr]">
              <div>
                <div className="mb-3 text-[10px] font-semibold uppercase tracking-[0.22em] text-slate-500">Gate</div>
                <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
                  {[1, 2, 3, 4].map((gate) => (
                    <button
                      key={gate}
                      type="button"
                      onClick={() => setSelectedGate(gate)}
                      className={cn(
                        "rounded-[1.15rem] border px-4 py-3 text-sm font-semibold transition-all",
                        selectedGate === gate
                          ? "border-amber-200/22 bg-amber-300/[0.10] text-white shadow-[0_12px_28px_rgba(180,138,61,0.14)]"
                          : "border-white/10 bg-black/20 text-slate-400 hover:border-white/20 hover:text-white"
                      )}
                    >
                      {gate}관문
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <div className="mb-3 text-[10px] font-semibold uppercase tracking-[0.22em] text-slate-500">Difficulty</div>
                <div className="flex flex-wrap gap-2">
                  {difficultyOptions.map((d) => (
                    <button
                      key={d}
                      type="button"
                      onClick={() => setDifficulty(d)}
                      className={cn(
                        "rounded-full border px-4 py-3 text-sm font-semibold transition-all",
                        difficulty === d
                          ? "border-white/10 bg-white text-black"
                          : "border-white/10 bg-black/20 text-slate-400 hover:border-white/20 hover:text-white"
                      )}
                    >
                      {d}
                    </button>
                  ))}
                </div>
              </div>

              <div className="rounded-[1.35rem] border border-white/10 bg-black/20 p-4">
                <div className="text-[10px] font-semibold uppercase tracking-[0.22em] text-slate-500">Current Slot</div>
                <div className="mt-3 text-lg font-semibold text-white">{difficulty}</div>
                <div className="mt-1 text-sm text-amber-200">{selectedGate}관문</div>
                <div className="mt-2 text-xs leading-5 text-slate-500">이 위치에 저장되는 메모/보상/수치가 모달에 그대로 연결돼.</div>
              </div>
            </div>
          </AdminSectionCard>
        )}

        <div className="grid gap-5 xl:grid-cols-[0.95fr,1.05fr]">
          <AdminSectionCard
            title="전투 수치"
            description="관문별 핵심 스펙과 숫자형 보상을 입력해."
          >
            <div className="grid gap-4 md:grid-cols-3">
              <AdminInput
                label="HP (체력)"
                value={form.hp}
                onChange={(v: any) => setForm({ ...form, hp: v })}
                placeholder="예: 12,500,000"
              />
              <AdminInput
                label="클리어 골드"
                type="number"
                value={form.gold}
                onChange={(v: any) => setForm({ ...form, gold: v })}
                placeholder="예: 2750"
              />
              <AdminInput
                label="더보기 골드"
                type="number"
                value={form.more_gold}
                onChange={(v: any) => setForm({ ...form, more_gold: v })}
                placeholder="예: 1820"
              />
            </div>
            <div className="mt-4 grid gap-4 md:grid-cols-2">
              <AdminSelect
                label="계열"
                value={form.element}
                onChange={(value) => setForm({ ...form, element: value })}
                options={elementOptions}
                placeholder="계열 선택"
              />
              <AdminSelect
                label="속성"
                value={form.attribute}
                onChange={(value) => setForm({ ...form, attribute: value })}
                options={attributeOptions}
                placeholder="속성 선택"
              />
            </div>
            <div className="mt-4">
              <div className="mb-2 flex items-center justify-between">
                <div className="text-[10px] font-semibold uppercase tracking-[0.22em] text-slate-500">필요 배틀아이템</div>
                <button
                  type="button"
                  onClick={() => setShowAddBattleItem(p => !p)}
                  className="flex items-center gap-1 rounded-full border border-dashed border-amber-400/30 bg-amber-400/8 px-2.5 py-1 text-[10px] font-semibold text-amber-300 hover:border-amber-400/50 transition-all"
                >
                  <Plus size={10} /> 직접 추가
                </button>
              </div>

              {/* 커스텀 배틀아이템 추가 폼 */}
              {showAddBattleItem && (
                <div className="mb-3 rounded-2xl border border-amber-400/15 bg-amber-400/5 p-3 space-y-2">
                  <div className="flex gap-2">
                    <input
                      value={newBattleItem.name}
                      onChange={e => setNewBattleItem(p => ({ ...p, name: e.target.value }))}
                      placeholder="아이템 이름"
                      className="flex-1 rounded-xl border border-white/10 bg-black/30 px-3 py-1.5 text-xs text-white outline-none focus:border-amber-400/30"
                    />
                    <input
                      value={newBattleItem.icon}
                      onChange={e => setNewBattleItem(p => ({ ...p, icon: e.target.value }))}
                      placeholder="이모지"
                      className="w-16 rounded-xl border border-white/10 bg-black/30 px-3 py-1.5 text-xs text-white outline-none text-center focus:border-amber-400/30"
                    />
                  </div>
                  <div className="flex items-center gap-2">
                    <label className="flex cursor-pointer items-center gap-2 rounded-xl border border-white/10 bg-black/20 px-3 py-1.5 text-xs text-slate-400 hover:border-white/20 transition-all">
                      <ImageIcon size={12} />
                      {uploadingBattleIcon ? "업로드 중..." : newBattleItem.image_url ? "이미지 변경" : "이미지 업로드"}
                      <input type="file" accept="image/*" className="hidden" onChange={e => { if (e.target.files?.[0]) uploadBattleIcon(e.target.files[0]); }} />
                    </label>
                    {newBattleItem.image_url && (
                      <img src={newBattleItem.image_url} alt="" className="h-8 w-8 rounded-lg object-cover border border-white/10" />
                    )}
                  </div>
                  <div className="flex gap-2">
                    <button
                      type="button"
                      onClick={async () => {
                        if (!newBattleItem.name.trim()) return;
                        await saveCustomBattleItem({ ...newBattleItem, name: newBattleItem.name.trim() });
                        setNewBattleItem({ name:"", icon:"🎒", image_url:"" });
                        setShowAddBattleItem(false);
                      }}
                      disabled={savingBattleItem}
                      className="flex-1 rounded-xl border border-amber-400/30 bg-amber-400/15 py-1.5 text-xs font-semibold text-amber-200 hover:bg-amber-400/25 transition-all disabled:opacity-50"
                    >{savingBattleItem ? "저장 중..." : "추가"}</button>
                    <button type="button" onClick={() => setShowAddBattleItem(false)}
                      className="rounded-xl border border-white/10 bg-black/20 px-3 py-1.5 text-xs text-slate-400 hover:text-white transition-all">취소</button>
                  </div>
                </div>
              )}

              <div className="flex flex-wrap gap-2">
                {allBattleItemDefs.map((itemDef) => {
                  const selected = (form.battle_items || "").split(",").map((s: string) => s.trim()).filter(Boolean).includes(itemDef.name);
                  return (
                    <div key={itemDef.name} className="relative group">
                      <button
                        type="button"
                        onClick={() => {
                          const current = (form.battle_items || "").split(",").map((s: string) => s.trim()).filter(Boolean);
                          const next = selected ? current.filter((v: string) => v !== itemDef.name) : [...current, itemDef.name];
                          setForm({ ...form, battle_items: next.join(", ") });
                        }}
                        className={cn(
                          "flex items-center gap-1.5 rounded-full border px-3 py-1.5 text-xs font-semibold transition-all",
                          selected
                            ? "border-amber-400/50 bg-amber-400/20 text-amber-200"
                            : "border-white/10 bg-black/20 text-slate-400 hover:border-white/20 hover:text-white"
                        )}
                      >
                        {itemDef.image_url
                          ? <img src={itemDef.image_url} alt="" className="h-4 w-4 rounded object-cover" />
                          : <span>{itemDef.icon}</span>
                        }
                        {itemDef.name}
                      </button>
                      {/* 커스텀 아이템 삭제 버튼 */}
                      {customBattleItems.some(c => c.name === itemDef.name) && (
                        <button
                          type="button"
                          onClick={() => {
                            const found = customBattleItems.find(c => c.name === itemDef.name);
                            if (found?.id) deleteCustomBattleItem(found.id, found.name);
                          }}
                          className="absolute -top-1.5 -right-1.5 hidden group-hover:flex h-4 w-4 items-center justify-center rounded-full bg-rose-500 text-white text-[9px] shadow"
                        >✕</button>
                      )}
                    </div>
                  );
                })}
              </div>
              {form.battle_items && (
                <div className="mt-2 text-[11px] text-slate-500">선택됨: {form.battle_items}</div>
              )}
            </div>
          </AdminSectionCard>

          <AdminSectionCard
            title="보상 데이터"
            description="클리어 보상 이미지를 업로드하거나 URL을 입력하세요."
          >
            <div className="space-y-4">
              {/* 보상 대표 이미지 */}
              <div className="space-y-2">
                <label className="ml-1 text-[10px] font-semibold uppercase tracking-[0.24em] text-slate-500">보상 대표 이미지</label>
                <div className="flex items-center gap-3">
                  <label className={cn(
                    "flex cursor-pointer items-center gap-2 rounded-2xl border border-dashed border-white/15 bg-black/20 px-4 py-3 text-xs text-slate-400 hover:border-amber-400/30 hover:text-amber-200 transition-all",
                    uploadingRewardImg && "opacity-50 pointer-events-none"
                  )}>
                    <ImageIcon size={13} />
                    {uploadingRewardImg ? "업로드 중..." : form.reward_image_url ? "이미지 변경" : "이미지 업로드"}
                    <input
                      type="file"
                      accept="image/*"
                      className="hidden"
                      onChange={e => { if (e.target.files?.[0]) uploadRewardImage(e.target.files[0]); }}
                    />
                  </label>
                  {form.reward_image_url && (
                    <div className="relative group">
                      <img src={form.reward_image_url} alt="보상 이미지" className="h-16 w-16 rounded-2xl object-cover border border-white/10" />
                      <button
                        type="button"
                        onClick={() => setForm((p: any) => ({ ...p, reward_image_url: "" }))}
                        className="absolute -top-2 -right-2 hidden group-hover:flex h-5 w-5 items-center justify-center rounded-full bg-rose-500 text-white text-[10px] shadow"
                      >✕</button>
                    </div>
                  )}
                </div>
                {form.reward_image_url && (
                  <div className="flex gap-2 items-center">
                    <input
                      value={form.reward_image_url}
                      onChange={e => setForm((p: any) => ({ ...p, reward_image_url: e.target.value }))}
                      placeholder="또는 URL 직접 입력"
                      className="flex-1 rounded-xl border border-white/10 bg-black/30 px-3 py-1.5 text-xs text-white outline-none focus:border-amber-400/30"
                    />
                  </div>
                )}
                {!form.reward_image_url && (
                  <input
                    value={form.reward_image_url}
                    onChange={e => setForm((p: any) => ({ ...p, reward_image_url: e.target.value }))}
                    placeholder="또는 URL 직접 입력"
                    className="w-full rounded-xl border border-white/10 bg-black/30 px-3 py-1.5 text-xs text-white outline-none focus:border-amber-400/30"
                  />
                )}
              </div>
            </div>
          </AdminSectionCard>
        </div>


        {isRaid && (
          <AdminSectionCard
            title="공대장 스킬"
            description="관문별 공대장이 사용하는 스킬을 최대 3개 등록할 수 있어. 이미지 + 이름 + 설명을 입력해."
          >
            <div className="space-y-4">
              {([1, 2, 3] as const).map((num) => {
                const imgKey  = `raid_skill_${num}_image`;
                const nameKey = `raid_skill_${num}_name`;
                const descKey = `raid_skill_${num}_desc`;
                return (
                  <div key={num} className="rounded-2xl border border-white/8 bg-white/[0.025] p-4">
                    <div className="mb-3 flex items-center gap-2">
                      <div className="flex h-6 w-6 items-center justify-center rounded-lg bg-amber-400/20 text-[11px] font-bold text-amber-300">{num}</div>
                      <span className="text-[11px] font-semibold uppercase tracking-widest text-stone-400">스킬 {num}</span>
                    </div>
                    <div className="grid gap-3 sm:grid-cols-[120px,1fr]">
                      {/* 이미지 */}
                      <div className="flex flex-col gap-2">
                        {form[imgKey] ? (
                          <div className="relative group">
                            <img src={form[imgKey]} alt={`스킬 ${num}`} className="h-24 w-full rounded-xl object-cover border border-white/10" />
                            <button
                              type="button"
                              onClick={() => setForm((p: any) => ({ ...p, [imgKey]: "" }))}
                              className="absolute -top-2 -right-2 hidden group-hover:flex h-5 w-5 items-center justify-center rounded-full bg-rose-500 text-white text-[10px] shadow"
                            >✕</button>
                          </div>
                        ) : (
                          <div className="flex h-24 items-center justify-center rounded-xl border border-dashed border-white/15 bg-black/20 text-xs text-stone-600">
                            이미지 없음
                          </div>
                        )}
                        <label className="flex cursor-pointer items-center justify-center gap-1.5 rounded-xl border border-dashed border-white/15 bg-black/10 py-2 text-[11px] text-stone-500 hover:border-amber-400/30 hover:text-amber-300 transition-all">
                          <ImageIcon size={11} />
                          {form[imgKey] ? "변경" : "업로드"}
                          <input
                            type="file" accept="image/*" className="hidden"
                            onChange={e => { if (e.target.files?.[0]) uploadRaidSkillImage(e.target.files[0], num); }}
                          />
                        </label>
                      </div>
                      {/* 이름 + 설명 */}
                      <div className="flex flex-col gap-2">
                        <input
                          value={form[nameKey]}
                          onChange={e => setForm((p: any) => ({ ...p, [nameKey]: e.target.value }))}
                          placeholder={`스킬 ${num} 이름 (예: 연합군 스킬 · 광선 다발)`}
                          className="w-full rounded-xl border border-white/10 bg-black/30 px-3 py-2 text-xs text-white outline-none focus:border-amber-400/30 transition-all"
                        />
                        <textarea
                          value={form[descKey]}
                          onChange={e => setForm((p: any) => ({ ...p, [descKey]: e.target.value }))}
                          placeholder={`스킬 ${num} 설명을 입력해.`}
                          rows={4}
                          className="w-full rounded-xl border border-white/10 bg-black/30 px-3 py-2 text-xs leading-6 text-white outline-none focus:border-amber-400/30 transition-all resize-none"
                        />
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </AdminSectionCard>
        )}

        <div className="grid gap-5 xl:grid-cols-3">
          <AdminSectionCard
            title="공략 메모"
            description="전체 진행 흐름이나 주의사항을 적어."
          >
            <AdminTextarea
              label="Guide"
              value={form.guide}
              onChange={(value) => setForm({ ...form, guide: value })}
              placeholder="공략 메모를 입력"
              rows={6}
            />
          </AdminSectionCard>

          <AdminSectionCard
            title="주요 기믹"
            description="패턴, 카운터, 협동 포인트를 적어."
          >
            <AdminTextarea
              label="Mechanics"
              value={form.mechanics}
              onChange={(value) => setForm({ ...form, mechanics: value })}
              placeholder="기믹/패턴을 입력"
              rows={6}
            />
          </AdminSectionCard>

          <AdminSectionCard
            title="추천 포인트"
            description="실전 팁, 아이템 추천, 파티 조합 팁을 적어."
          >
            <AdminTextarea
              label="Tip"
              value={form.tip}
              onChange={(value) => setForm({ ...form, tip: value })}
              placeholder="추천 포인트를 입력"
              rows={6}
            />
          </AdminSectionCard>
        </div>

        <div className="flex flex-wrap gap-3">
          <button
            onClick={handleSave}
            className="rounded-[1.35rem] bg-gradient-to-r from-amber-400 to-amber-300 px-6 py-4 text-sm font-semibold text-slate-950 transition-all hover:brightness-110"
          >
            {editingId ? "Update Content" : "Register Content"}
          </button>

          {editingId && (
            <button
              onClick={resetForm}
              className="rounded-[1.35rem] border border-white/10 bg-white/[0.05] px-6 py-4 text-sm font-semibold text-slate-300 transition-all hover:bg-white/[0.08] hover:text-white"
            >
              Cancel
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

const ClassContentEditor = () => {
  const [list, setList] = useState<any[]>([]);
  const [form, setForm] = useState({
    root: "",
    sub: "",
    eng_job: "",
    link: "",
    image_url: "",
  });

  useEffect(() => {
    fetchList();
  }, []);

  const fetchList = async () => {
    const { data, error } = await supabase.from("class_infos").select("*").order("sub_class");
    if (error) {
      console.error(error);
      setList([]);
      return;
    }
    setList(data || []);
  };

  const handleSave = async () => {
    if (!form.sub) return showToast("직업명을 입력하세요.");
    const { error } = await supabase.from("class_infos").upsert(
      {
        root_class: form.root,
        sub_class: form.sub,
        engraving_job: form.eng_job,
        skill_code_link: form.link,
        image_url: form.image_url,
      },
      { onConflict: "sub_class" },
    );

    if (!error) {
      showToast("저장 완료!", "success");
      fetchList();
      setForm({ root: "", sub: "", eng_job: "", link: "", image_url: "" });
    } else {
      showToast(error.message, "error");
    }
  };

  const deleteItem = async (subClass: string) => {
    if (!confirm(`[${subClass}] 클래스를 삭제하시겠습니까?`)) return;
    const { error } = await supabase.from("class_infos").delete().eq("sub_class", subClass);
    if (!error) {
      showToast("삭제 완료", "success");
      fetchList();
    }
  };

  return (
    <div className="grid md:grid-cols-2 gap-12">
      <div className="space-y-6">
        <h4 className="text-xs font-semibold uppercase text-amber-400 tracking-widest">
          Class List
        </h4>
        <div className="grid grid-cols-2 gap-2 max-h-[500px] overflow-y-auto pr-2">
          {list.map((item) => (
            <div
              key={item.id || item.sub_class}
              className="flex items-center justify-between bg-black/40 p-3 rounded-xl border border-white/5"
            >
              <span className="text-[10px] font-bold text-slate-400">{item.sub_class}</span>
              <button
                onClick={() => deleteItem(item.sub_class)}
                className="text-slate-600 hover:text-red-500 transition-colors"
              >
                <Trash2 size={14} />
              </button>
            </div>
          ))}
        </div>
      </div>

      <div className="space-y-6">
        <div className="grid grid-cols-2 gap-4">
          <AdminInput label="Root" value={form.root} onChange={(v: any) => setForm({ ...form, root: v })} />
          <AdminInput label="Sub" value={form.sub} onChange={(v: any) => setForm({ ...form, sub: v })} />
        </div>
        <AdminInput
          label="Job Engraving"
          value={form.eng_job}
          onChange={(v: any) => setForm({ ...form, eng_job: v })}
        />
        <AdminInput
          label="Guide Link"
          value={form.link}
          onChange={(v: any) => setForm({ ...form, link: v })}
        />
        <ImageUploader
          label="Class Image"
          onUpload={(url) => setForm({ ...form, image_url: url })}
        />
        <button
          onClick={handleSave}
          className="w-full bg-amber-500 p-4 rounded-xl font-semibold uppercase hover:bg-amber-400 transition-all"
        >
          Update Class
        </button>
      </div>
    </div>
  );
};



// ── 카테고리 정의 ──────────────────────────────────────────
const POST_CATEGORIES = [
  { key: "all",   label: "전체",     color: "" },
  { key: "notice",label: "공지",     color: "text-amber-200 bg-amber-400/15 border-amber-400/20" },
  { key: "자유",  label: "자유",     color: "text-slate-200 bg-white/10 border-white/10" },
  { key: "공략",  label: "공략",     color: "text-emerald-200 bg-emerald-400/15 border-emerald-400/20" },
  { key: "레이드후기", label: "레이드후기", color: "text-violet-200 bg-violet-400/15 border-violet-400/20" },
  { key: "질문",  label: "질문",     color: "text-sky-200 bg-sky-400/15 border-sky-400/20" },
  { key: "스크린샷", label: "스크린샷", color: "text-pink-200 bg-pink-400/15 border-pink-400/20" },
];

const getCategoryStyle = (cat: string, isNotice: boolean) => {
  if (isNotice) return "text-amber-200 bg-amber-400/15 border-amber-400/20";
  return POST_CATEGORIES.find((c) => c.key === cat)?.color || "text-slate-200 bg-white/10 border-white/10";
};

// ── YouTube URL 파싱 ───────────────────────────────────────
const extractYoutubeId = (text: string): string | null => {
  const m = text.match(/(?:youtu\.be\/|youtube\.com\/(?:watch\?v=|embed\/|shorts\/))([\w-]{11})/);
  return m ? m[1] : null;
};

// ── 이미지 라이트박스 ──────────────────────────────────────
const ImageLightbox = ({ src, onClose }: { src: string; onClose: () => void }) => (
  <AnimatePresence>
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 z-[300] flex items-center justify-center bg-black/90 backdrop-blur-xl p-4"
      onClick={onClose}
    >
      <motion.img
        initial={{ scale: 0.9, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        src={src}
        className="max-h-[90vh] max-w-[90vw] rounded-2xl object-contain shadow-2xl"
        onClick={(e) => e.stopPropagation()}
      />
      <button
        onClick={onClose}
        className="absolute top-4 right-4 flex h-10 w-10 items-center justify-center rounded-full bg-white/10 text-white hover:bg-white/20 transition"
      >
        <X size={20} />
      </button>
    </motion.div>
  </AnimatePresence>
);

// ── 게시글 상세 모달 ───────────────────────────────────────
const PostDetailModal = ({ post, comments, user, profile, onClose, onDelete, onTogglePin, onSubmitComment, onDeleteComment, onRefresh }: any) => {
  const [commentDraft, setCommentDraft] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [lightboxSrc, setLightboxSrc] = useState<string | null>(null);
  const [reactions, setReactions] = useState<Record<string, number>>({});
  const [myReactions, setMyReactions] = useState<Record<string, boolean>>({});
  const [reactionsLoaded, setReactionsLoaded] = useState(false);

  const youtubeId = post.youtube_url ? extractYoutubeId(post.youtube_url) : extractYoutubeId(post.content || "");

  // 조회수 증가 — 세션당 1회만
  useEffect(() => {
    const key = `viewed_post_${post.id}`;
    if (sessionStorage.getItem(key)) return;
    sessionStorage.setItem(key, "1");
    const client = getSupabaseOrThrow();
    client.rpc("increment_post_views", { p_post_id: post.id }).then(() => {});
  }, [post.id]);

  // 반응 불러오기 — 항상 DB에서 최신 값 fetch
  const loadReactions = async () => {
    try {
      const client = getSupabaseOrThrow();
      const { data } = await client
        .from("post_reactions")
        .select("emoji, user_id")
        .eq("post_id", post.id);
      if (!data) return;
      const counts: Record<string, number> = {};
      const mine: Record<string, boolean> = {};
      data.forEach((r: any) => {
        counts[r.emoji] = (counts[r.emoji] || 0) + 1;
        if (user && r.user_id === user.id) mine[r.emoji] = true;
      });
      setReactions(counts);
      setMyReactions(mine);
      setReactionsLoaded(true);
    } catch { setReactionsLoaded(true); }
  };

  useEffect(() => { void loadReactions(); }, [post.id, user]);

  const toggleReaction = async (emoji: string) => {
    if (!user) return showToast("로그인 후 반응을 남길 수 있어요.", "error");
    // 낙관적 업데이트
    const wasOn = myReactions[emoji];
    setReactions((p) => ({ ...p, [emoji]: Math.max(0, (p[emoji] || 0) + (wasOn ? -1 : 1)) }));
    setMyReactions((p) => ({ ...p, [emoji]: !wasOn }));
    try {
      const client = getSupabaseOrThrow();
      if (wasOn) {
        await client.from("post_reactions").delete()
          .eq("post_id", post.id).eq("user_id", user.id).eq("emoji", emoji);
      } else {
        await client.from("post_reactions").insert({ post_id: post.id, user_id: user.id, emoji });
      }
      // DB 확정 후 정확한 값으로 재동기화
      await loadReactions();
    } catch {
      // 실패 시 롤백
      setReactions((p) => ({ ...p, [emoji]: Math.max(0, (p[emoji] || 0) + (wasOn ? 1 : -1)) }));
      setMyReactions((p) => ({ ...p, [emoji]: wasOn }));
      showToast("반응 처리 중 오류가 발생했어요.", "error");
    }
  };

  const handleSubmitComment = async () => {
    const content = commentDraft.trim();
    if (!content) return;
    setSubmitting(true);
    await onSubmitComment(post.id, content);
    setCommentDraft("");
    setSubmitting(false);
  };

  const EMOJIS = ["👍", "❤️", "😂", "😮", "🔥", "🎉"];

  return (
    <>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 z-[200] flex items-start justify-center overflow-y-auto bg-[rgba(2,6,23,0.80)] px-3 py-4 backdrop-blur-xl sm:p-6"
        onClick={onClose}
      >
        <motion.div
          initial={{ opacity: 0, y: 20, scale: 0.98 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          exit={{ opacity: 0, y: 12, scale: 0.98 }}
          transition={{ duration: 0.22 }}
          className="relative w-full max-w-3xl overflow-hidden rounded-[2rem] border border-white/10 bg-[#0e0b08]/97 shadow-[0_32px_80px_rgba(2,6,23,0.6)] backdrop-blur-2xl my-2"
          onClick={(e) => e.stopPropagation()}
        >
          {/* 헤더 */}
          <div className="relative border-b border-white/8 px-5 py-5 sm:px-7 sm:py-6">
            <div className="flex items-start justify-between gap-4">
              <div className="min-w-0 flex-1">
                <div className="flex flex-wrap items-center gap-2 mb-3">
                  {post.is_pinned && (
                    <span className="inline-flex items-center gap-1 rounded-full border border-rose-400/20 bg-rose-400/12 px-2.5 py-1 text-[10px] font-semibold text-rose-300">
                      <Pin size={10} /> PIN
                    </span>
                  )}
                  <span className={cn("inline-flex rounded-full border px-2.5 py-1 text-[10px] font-semibold", getCategoryStyle(post.category, post.is_notice))}>
                    {post.is_notice ? "공지" : (post.category || "자유")}
                  </span>
                  <span className="text-[11px] text-stone-500">{formatDateTime(post.created_at)}</span>
                  {(post.views || 0) > 0 && (
                    <span className="text-[11px] text-stone-500">👁 {post.views}</span>
                  )}
                </div>
                <h2 className="text-xl font-semibold leading-snug text-white sm:text-2xl">{post.title}</h2>
                <div className="mt-2 flex items-center gap-2">
                  <span className="text-sm font-semibold text-amber-100/80">{post.author_name || post.author || "익명"}</span>
                </div>
              </div>
              <div className="flex shrink-0 items-center gap-2">
                {isStaffRole(profile?.role) && post.is_notice && (
                  <button onClick={() => onTogglePin(post)} className="rounded-xl border border-amber-200/20 bg-amber-300/10 px-3 py-2 text-[11px] font-semibold text-amber-200 hover:bg-amber-300/16 transition">
                    {post.is_pinned ? "고정 해제" : "고정"}
                  </button>
                )}
                {(isStaffRole(profile?.role) || user?.id === post.user_id) && (
                  <button onClick={() => { onDelete(post.id); onClose(); }} className="flex h-9 w-9 items-center justify-center rounded-xl border border-white/10 bg-white/[0.04] text-slate-500 hover:border-rose-400/20 hover:bg-rose-400/10 hover:text-rose-300 transition">
                    <Trash2 size={15} />
                  </button>
                )}
                <button onClick={onClose} className="flex h-9 w-9 items-center justify-center rounded-xl border border-white/10 bg-white/[0.04] text-slate-400 hover:text-white transition">
                  <X size={18} />
                </button>
              </div>
            </div>
          </div>

          {/* 본문 */}
          <div className="max-h-[60vh] overflow-y-auto px-5 py-5 sm:px-7 sm:py-6 space-y-5">
            {/* 이미지 */}
            {post.image_url && (
              <div
                className="cursor-zoom-in overflow-hidden rounded-2xl border border-white/10"
                onClick={() => setLightboxSrc(post.image_url)}
              >
                <img src={post.image_url} className="w-full max-h-[400px] object-cover hover:scale-[1.02] transition-transform duration-300" />
                <div className="px-3 py-1.5 text-[10px] text-stone-500">클릭하면 원본 크기로 볼 수 있어</div>
              </div>
            )}

            {/* 유튜브 */}
            {youtubeId && (
              <div className="overflow-hidden rounded-2xl border border-white/10 aspect-video">
                <iframe
                  src={`https://www.youtube.com/embed/${youtubeId}`}
                  className="w-full h-full"
                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                  allowFullScreen
                />
              </div>
            )}

            {/* 내용 */}
            <p className="whitespace-pre-wrap text-sm leading-7 text-stone-300">{post.content}</p>

            {/* 이모지 반응 */}
            <div className="border-t border-white/8 pt-4">
              <div className="flex flex-wrap gap-2">
                {EMOJIS.map((emoji) => (
                  <button
                    key={emoji}
                    onClick={() => toggleReaction(emoji)}
                    className={cn(
                      "flex items-center gap-1.5 rounded-full border px-3 py-1.5 text-sm transition-all",
                      myReactions[emoji]
                        ? "border-amber-400/40 bg-amber-400/15 text-amber-100"
                        : "border-white/10 bg-white/[0.04] text-slate-300 hover:border-white/20 hover:bg-white/[0.08]"
                    )}
                  >
                    <span>{emoji}</span>
                    {(reactions[emoji] || 0) > 0 && (
                      <span className="text-xs font-semibold">{reactions[emoji]}</span>
                    )}
                  </button>
                ))}
              </div>
            </div>

            {/* 댓글 */}
            <div className="border-t border-white/8 pt-4 space-y-3">
              <div className="text-xs font-semibold uppercase tracking-[0.18em] text-stone-500">
                댓글 {comments.length}개
              </div>
              {comments.length === 0 && (
                <div className="text-sm text-stone-500">아직 댓글이 없어. 첫 댓글을 남겨봐!</div>
              )}
              {comments.map((comment: any) => (
                <div key={comment.id} className="rounded-2xl border border-white/8 bg-white/[0.03] px-4 py-3">
                  <div className="flex items-start justify-between gap-3">
                    <div>
                      <span className="text-sm font-semibold text-white">{comment.author_name || comment.author || "익명"}</span>
                      <span className="ml-2 text-[10px] text-stone-500">{formatDateTime(comment.created_at)}</span>
                    </div>
                    {(isStaffRole(profile?.role) || user?.id === comment.user_id) && (
                      <button onClick={() => onDeleteComment(comment.id)} className="text-slate-600 hover:text-rose-400 transition">
                        <Trash2 size={13} />
                      </button>
                    )}
                  </div>
                  <p className="mt-2 text-sm text-stone-300 whitespace-pre-wrap">{comment.content}</p>
                </div>
              ))}

              {user && (
                <div className="flex gap-2 pt-1">
                  <textarea
                    value={commentDraft}
                    onChange={(e) => setCommentDraft(e.target.value)}
                    placeholder="댓글 작성 시 +5P 지급"
                    rows={2}
                    className="flex-1 resize-none rounded-2xl border border-white/10 bg-black/30 px-4 py-3 text-sm text-white outline-none placeholder:text-stone-600 focus:border-amber-200/25"
                  />
                  <button
                    onClick={handleSubmitComment}
                    disabled={submitting || !commentDraft.trim()}
                    className="flex h-auto w-14 shrink-0 items-center justify-center rounded-2xl bg-amber-500 text-black hover:bg-amber-400 transition disabled:opacity-40"
                  >
                    <Send size={16} />
                  </button>
                </div>
              )}
            </div>
          </div>
        </motion.div>
      </motion.div>

      {lightboxSrc && <ImageLightbox src={lightboxSrc} onClose={() => setLightboxSrc(null)} />}
    </>
  );
};

// ── PostBoard ──────────────────────────────────────────────
const PostBoard = ({ posts, user, profile, onRefresh, initialTab, lockedCategory }: any) => {
  // lockedCategory: "notice" | "자유" | "질문" | "공략" | undefined
  // 지정되면 카테고리 탭 UI 숨김 + 해당 카테고리만 표시 + 헤더 타이틀 자동 변경
  const [tab, setTab] = useState(lockedCategory || initialTab || "all");
  const [search, setSearch] = useState("");
  const [showWriteModal, setShowWriteModal] = useState(false);
  const [selectedPost, setSelectedPost] = useState<any>(null);
  const [commentsByPost, setCommentsByPost] = useState<Record<string, any[]>>({});
  const [commentsEnabled, setCommentsEnabled] = useState(true);

  // lockedCategory가 바뀌면 tab도 자동 동기화 (라우팅 시)
  useEffect(() => {
    if (lockedCategory) setTab(lockedCategory);
  }, [lockedCategory]);

  const visiblePosts = useMemo(() => {
    const pinned = posts.filter((p: any) => p.is_pinned).sort((a: any, b: any) => +new Date(b.created_at) - +new Date(a.created_at));
    const normal = posts.filter((p: any) => !p.is_pinned).sort((a: any, b: any) => +new Date(b.created_at) - +new Date(a.created_at));
    let merged = [...pinned, ...normal];
    const effectiveTab = lockedCategory || tab;
    if (effectiveTab === "notice") merged = merged.filter((p: any) => p.is_notice);
    else if (effectiveTab !== "all") merged = merged.filter((p: any) => !p.is_notice && p.category === effectiveTab);
    if (search.trim()) {
      const q = search.toLowerCase();
      merged = merged.filter((p: any) =>
        (p.title || "").toLowerCase().includes(q) ||
        (p.content || "").toLowerCase().includes(q) ||
        (p.author_name || "").toLowerCase().includes(q)
      );
    }
    return merged;
  }, [posts, tab, search, lockedCategory]);

  const fetchComments = useCallback(async () => {
    if (!posts || posts.length === 0) { setCommentsByPost({}); return; }
    try {
      const client = getSupabaseOrThrow();
      const postIds = posts.map((p: any) => p.id).filter(Boolean);
      if (!postIds.length) { setCommentsByPost({}); return; }
      const { data, error } = await client.from("post_comments").select("*").in("post_id", postIds).order("created_at", { ascending: true });
      if (error) { setCommentsEnabled(false); setCommentsByPost({}); return; }
      setCommentsEnabled(true);
      setCommentsByPost((data || []).reduce((acc: Record<string, any[]>, item: any) => {
        const k = String(item.post_id); acc[k] = acc[k] || []; acc[k].push(item); return acc;
      }, {}));
    } catch { setCommentsEnabled(false); setCommentsByPost({}); }
  }, [posts]);

  useEffect(() => { void fetchComments(); }, [fetchComments]);

  const handleDelete = async (postId: string) => {
    if (!confirm("게시글을 삭제할까요?")) return;
    try {
      const client = getSupabaseOrThrow();
      try { await client.from("post_comments").delete().eq("post_id", postId); } catch {}
      const { error } = await client.from("posts").delete().eq("id", postId);
      if (error) return showToast(error.message, "error");
      setSelectedPost(null);
      onRefresh(); void fetchComments();
    } catch (e: any) { showToast(e?.message || "삭제 오류", "error"); }
  };

  const togglePin = async (post: any) => {
    if (!isStaffRole(profile?.role) || !post.is_notice) return;
    const client = getSupabaseOrThrow();
    if (!post.is_pinned) await client.from("posts").update({ is_pinned: false }).eq("is_notice", true).eq("is_pinned", true);
    const { error } = await client.from("posts").update({ is_pinned: !post.is_pinned }).eq("id", post.id);
    if (error) return showToast(error.message, "error");
    onRefresh();
  };

  const submitComment = async (postId: string, content: string) => {
    if (!user) return showToast("로그인 후 댓글을 작성할 수 있어요.", "error");
    if (!commentsEnabled) return showToast("댓글 기능용 SQL이 아직 적용되지 않았어요.", "error");
    try {
      const client = getSupabaseOrThrow();
      const { error } = await client.from("post_comments").insert([{ post_id: postId, content, user_id: user.id, author: profile?.nickname || "Anonymous", author_name: profile?.nickname || "Anonymous" }]);
      if (error) { showToast(error.message, "error"); return; }
      await client.rpc("add_points", { p_user_id: user.id, p_points: 5, p_type: "comment" });
      await fetchComments();
      // 선택된 게시글 댓글 갱신
      setSelectedPost((prev: any) => prev ? { ...prev } : prev);
      showToast("댓글 작성 완료! +5P 🎉", "success");
    } catch (e: any) { showToast(e?.message || "댓글 등록 오류", "error"); }
  };

  const deleteComment = async (commentId: string) => {
    if (!confirm("댓글을 삭제할까요?")) return;
    try {
      const client = getSupabaseOrThrow();
      const { error } = await client.from("post_comments").delete().eq("id", commentId);
      if (error) { showToast(error.message, "error"); return; }
      await fetchComments();
    } catch (e: any) { showToast(e?.message || "댓글 삭제 오류", "error"); }
  };

  if (!user) return (
    <div className="max-w-2xl mx-auto py-32 text-center space-y-6">
      <Shield size={64} className="mx-auto text-slate-800" />
      <h2 className="text-2xl sm:text-3xl font-semibold uppercase tracking-tight">Access Denied</h2>
      <p className="text-slate-500 font-bold">게시판은 로그인한 회원만 이용 가능합니다.</p>
    </div>
  );

  // 페이지별 메타 (lockedCategory 기준)
  const pageMeta = useMemo(() => {
    switch (lockedCategory) {
      case "notice":
        return { title: "공지사항", sub: "운영 공지 · 길드 알림", accent: "#fbbf24", accentR: "251,191,36", icon: "📢" };
      case "자유":
        return { title: "자유 게시판", sub: "잡담 · 일상 · 게시글 +5P · 댓글 +5P", accent: "#a78bfa", accentR: "167,139,250", icon: "💬" };
      case "질문":
        return { title: "질문 게시판", sub: "공략 · 세팅 · 운영 관련 질문", accent: "#22d3ee", accentR: "34,211,238", icon: "❓" };
      case "공략":
        return { title: "공략 노트", sub: "레이드 · 세팅 · 빌드 노하우", accent: "#34d399", accentR: "52,211,153", icon: "📖" };
      default:
        return { title: "Bulletin Board", sub: "게시글 +5P · 댓글 +5P", accent: "#a78bfa", accentR: "167,139,250", icon: "📋" };
    }
  }, [lockedCategory]);

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="max-w-6xl mx-auto px-4 py-8 md:px-12 md:py-12 text-left">
      {/* 헤더 */}
      <div className="flex flex-col md:flex-row md:items-end md:justify-between gap-4 mb-8">
        <div className="flex items-start gap-3">
          {lockedCategory && (
            <div
              className="flex h-12 w-12 items-center justify-center rounded-2xl text-2xl shrink-0 mt-1"
              style={{
                background: `rgba(${pageMeta.accentR},0.12)`,
                border: `1px solid rgba(${pageMeta.accentR},0.28)`,
              }}
            >
              {pageMeta.icon}
            </div>
          )}
          <div>
            <h2 className="text-2xl sm:text-3xl font-semibold tracking-tight md:text-4xl">{pageMeta.title}</h2>
            <p className="text-slate-500 text-sm mt-2">{pageMeta.sub}</p>
          </div>
        </div>
        <button
          onClick={() => setShowWriteModal(true)}
          className="flex items-center gap-2 rounded-2xl px-5 py-3 font-semibold text-sm text-black shadow-lg transition"
          style={{
            background: `linear-gradient(160deg, ${pageMeta.accent}, ${pageMeta.accent}dd)`,
            boxShadow: `0 4px 20px rgba(${pageMeta.accentR},0.30)`,
          }}
        >
          <Plus size={17} /> 글 작성
        </button>
      </div>

      {/* 검색 + 카테고리 필터 (lockedCategory 없을 때만 카테고리 칩 표시) */}
      <div className="mb-6 space-y-3">
        <div className="relative">
          <input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="제목, 내용, 작성자 검색..."
            className="w-full rounded-2xl border border-white/10 bg-white/[0.04] px-5 py-3.5 pr-10 text-sm text-white outline-none placeholder:text-stone-600 focus:border-amber-200/25 transition"
          />
          {search && (
            <button onClick={() => setSearch("")} className="absolute right-4 top-1/2 -translate-y-1/2 text-stone-500 hover:text-white">
              <X size={15} />
            </button>
          )}
        </div>
        {!lockedCategory && (
          <div className="flex flex-wrap gap-2">
            {POST_CATEGORIES.map(({ key, label }) => (
              <button
                key={key}
                onClick={() => setTab(key)}
                className={cn(
                  "rounded-full border px-4 py-2 text-[11px] font-semibold transition-all",
                  tab === key
                    ? "border-amber-400/40 bg-amber-400/15 text-amber-200"
                    : "border-white/10 bg-white/[0.04] text-slate-500 hover:border-white/20 hover:text-slate-300"
                )}
              >
                {label}
                {key !== "all" && (
                  <span className="ml-1.5 text-[10px] opacity-60">
                    {key === "notice"
                      ? posts.filter((p: any) => p.is_notice).length
                      : posts.filter((p: any) => !p.is_notice && p.category === key).length}
                  </span>
                )}
              </button>
            ))}
          </div>
        )}
      </div>

      {/* 게시글 목록 */}
      <div className="space-y-2">
        {visiblePosts.length === 0 && (
          <div className="rounded-[2rem] border border-dashed border-white/10 bg-white/[0.02] p-12 text-center text-stone-500">
            {search ? `"${search}" 검색 결과가 없어요.` : "게시글이 없어요."}
          </div>
        )}
        {visiblePosts.map((post: any) => {
          const postComments = commentsByPost[String(post.id)] || [];
          const youtubeId = post.youtube_url ? extractYoutubeId(post.youtube_url) : extractYoutubeId(post.content || "");
          return (
            <motion.div
              key={post.id}
              initial={{ opacity: 0, y: 6 }}
              animate={{ opacity: 1, y: 0 }}
              onClick={() => setSelectedPost(post)}
              className={cn(
                "group cursor-pointer rounded-[1.6rem] border px-5 py-4 transition-all hover:-translate-y-0.5 hover:shadow-[0_12px_28px_rgba(0,0,0,0.2)]",
                post.is_pinned
                  ? "border-amber-400/25 bg-amber-400/[0.07] hover:border-amber-400/40"
                  : "border-white/8 bg-white/[0.025] hover:border-white/16 hover:bg-white/[0.04]"
              )}
            >
              <div className="flex items-start gap-4">
                {/* 섬네일 */}
                {post.image_url && (
                  <div className="hidden sm:block shrink-0 h-14 w-20 overflow-hidden rounded-xl border border-white/10">
                    <img src={post.image_url} className="h-full w-full object-cover" />
                  </div>
                )}
                {!post.image_url && youtubeId && (
                  <div className="hidden sm:block shrink-0 h-14 w-20 overflow-hidden rounded-xl border border-white/10 bg-black">
                    <img src={`https://img.youtube.com/vi/${youtubeId}/mqdefault.jpg`} className="h-full w-full object-cover" />
                  </div>
                )}

                <div className="min-w-0 flex-1">
                  <div className="flex flex-wrap items-center gap-2 mb-1.5">
                    {post.is_pinned && (
                      <span className="inline-flex items-center gap-1 rounded-full border border-rose-400/20 bg-rose-400/10 px-2 py-0.5 text-[9px] font-semibold text-rose-300">
                        <Pin size={9} /> PIN
                      </span>
                    )}
                    <span className={cn("rounded-full border px-2 py-0.5 text-[9px] font-semibold", getCategoryStyle(post.category, post.is_notice))}>
                      {post.is_notice ? "공지" : (post.category || "자유")}
                    </span>
                  </div>
                  <div className="truncate text-sm font-semibold text-white group-hover:text-amber-100 transition-colors">
                    {post.title}
                  </div>
                  <div className="mt-1 flex flex-wrap items-center gap-3 text-[11px] text-stone-500">
                    <span className="font-medium text-stone-400">{post.author_name || post.author || "익명"}</span>
                    <span>{formatDateTime(post.created_at)}</span>
                    {(post.views || 0) > 0 && <span>👁 {post.views}</span>}
                    {postComments.length > 0 && <span>💬 {postComments.length}</span>}
                  </div>
                </div>
              </div>
            </motion.div>
          );
        })}
      </div>

      {/* 글쓰기 모달 */}
      <AnimatePresence>
        {showWriteModal && (
          <PostWriteModal
            user={user}
            profile={profile}
            onRefresh={async () => { await onRefresh(); await fetchComments(); }}
            onClose={() => setShowWriteModal(false)}
            defaultCategory={lockedCategory && lockedCategory !== "notice" ? lockedCategory : undefined}
            forceNotice={lockedCategory === "notice"}
          />
        )}
      </AnimatePresence>

      {/* 상세 모달 */}
      <AnimatePresence>
        {selectedPost && (
          <PostDetailModal
            post={selectedPost}
            comments={commentsByPost[String(selectedPost.id)] || []}
            user={user}
            profile={profile}
            onClose={() => setSelectedPost(null)}
            onDelete={handleDelete}
            onTogglePin={togglePin}
            onSubmitComment={submitComment}
            onDeleteComment={deleteComment}
            onRefresh={onRefresh}
          />
        )}
      </AnimatePresence>
    </motion.div>
  );
};

// ── PostWriteModal ─────────────────────────────────────────
const PostWriteModal = ({ user, profile, onRefresh, onClose, defaultCategory, forceNotice }: any) => {
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [category, setCategory] = useState(defaultCategory || "자유");
  const [imgUrl, setImgUrl] = useState("");
  const [youtubeUrl, setYoutubeUrl] = useState("");
  const [isNotice, setIsNotice] = useState(Boolean(forceNotice));
  const [isPinned, setIsPinned] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  const handlePost = async () => {
    if (!title.trim() || !content.trim()) { showToast("제목과 내용을 입력하세요."); return; }
    try {
      setSubmitting(true);
      const client = getSupabaseOrThrow();
      const { data, error } = await client.from("posts").insert([{
        title: title.trim(),
        content: content.trim(),
        category: isNotice ? "공지" : category,
        image_url: imgUrl || null,
        youtube_url: youtubeUrl.trim() || null,
        author: profile?.nickname || "Anonymous",
        author_name: profile?.nickname || "Anonymous",
        user_id: user.id,
        author_id: user.id,
        is_notice: Boolean(isNotice),
        is_pinned: isStaffRole(profile?.role) ? Boolean(isNotice && isPinned) : false,
        views: 0,
      }]).select().single();
      if (error) { showToast(error.message, "error"); return; }
      if (isStaffRole(profile?.role) && isNotice && isPinned) {
        await client.from("posts").update({ is_pinned: false }).neq("id", data.id).eq("is_notice", true).eq("is_pinned", true);
      }
      if (!isNotice) await client.rpc("add_points", { p_user_id: user.id, p_points: 5, p_type: "post" });
      // 🏆 글 작성 → 업적 자동 평가
      triggerAchievementEval(user?.id);
      showToast(isNotice ? "공지 작성 완료!" : "게시글 작성 완료! +5P 🎉");
      await onRefresh(); onClose();
    } catch (err: any) { showToast(err?.message || "작성 중 오류 발생", "error"); }
    finally { setSubmitting(false); }
  };

  const ytId = extractYoutubeId(youtubeUrl);

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
      className="fixed inset-0 z-[200] flex items-start justify-center overflow-y-auto bg-black/90 backdrop-blur-xl px-3 py-4 sm:p-6 text-left"
    >
      <div
        className="relative w-full max-w-2xl my-2 overflow-hidden backdrop-blur-2xl"
        style={{
          borderRadius: "var(--guild-radius-xl,24px)",
          border: "1px solid rgba(var(--ga-r400,167,139,250),0.18)",
          background: "linear-gradient(160deg, #0d1526 0%, #080c16 100%)",
          boxShadow: "0 0 0 1px rgba(var(--ga-r400,167,139,250),0.06) inset, 0 32px 80px rgba(0,0,0,0.65)",
          padding: "0",
        }}
      >
        {/* 상단 액센트 라인 */}
        <div className="absolute top-0 left-0 right-0 h-px" style={{ background: `linear-gradient(90deg,transparent,rgba(var(--ga-r400,167,139,250),0.7) 40%,rgba(var(--ga-r300,196,181,253),0.4) 60%,transparent)` }} />
        {/* 글로우 */}
        <div className="pointer-events-none absolute top-0 right-0 h-40 w-40 opacity-50" style={{ background: `radial-gradient(circle,rgba(var(--ga-r400,167,139,250),0.14),transparent 70%)` }} />

        {/* 헤더 */}
        <div className="relative flex items-start justify-between px-7 pt-7 pb-5" style={{ borderBottom: "1px solid rgba(255,255,255,0.06)" }}>
          <div>
            <div
              className="mb-2.5 inline-flex items-center gap-1.5 rounded-full px-3 py-1 text-[10px] font-semibold uppercase tracking-[0.22em]"
              style={{ background: `rgba(var(--ga-r400,167,139,250),0.12)`, border: `1px solid rgba(var(--ga-r400,167,139,250),0.22)`, color: `var(--ga-200,#ddd6fe)` }}
            >
              New Post
            </div>
            <h3 className="text-2xl font-semibold text-white">새 게시글 작성</h3>
            <p className="mt-1 text-sm" style={{ color: "var(--guild-text-3,#5C6882)" }}>일반 글 +5P · 댓글 +5P</p>
          </div>
          <button
            onClick={onClose}
            className="flex h-9 w-9 items-center justify-center rounded-xl transition-all"
            style={{ border: "1px solid rgba(255,255,255,0.08)", background: "rgba(255,255,255,0.04)", color: "var(--guild-text-3,#5C6882)" }}
            onMouseEnter={e => { (e.currentTarget as HTMLButtonElement).style.background=`rgba(var(--ga-r400,167,139,250),0.12)`; (e.currentTarget as HTMLButtonElement).style.borderColor=`rgba(var(--ga-r400,167,139,250),0.28)`; (e.currentTarget as HTMLButtonElement).style.color=`var(--ga-200,#ddd6fe)`; }}
            onMouseLeave={e => { (e.currentTarget as HTMLButtonElement).style.background="rgba(255,255,255,0.04)"; (e.currentTarget as HTMLButtonElement).style.borderColor="rgba(255,255,255,0.08)"; (e.currentTarget as HTMLButtonElement).style.color="var(--guild-text-3,#5C6882)"; }}
          >
            <X size={16} />
          </button>
        </div>
        <div className="relative px-7 py-6" style={{ paddingBottom: "1.75rem" }}>

        <div className="space-y-4">
          {/* 카테고리 + 관리자 옵션 */}
          <div className="flex flex-wrap gap-3">
            <select
              value={category}
              onChange={(e) => setCategory(e.target.value)}
              disabled={isNotice}
              className="rounded-2xl border border-white/10 bg-black/40 px-4 py-3 text-sm font-semibold text-white outline-none focus:border-amber-200/25 disabled:opacity-50"
            >
              {POST_CATEGORIES.filter((c) => c.key !== "all" && c.key !== "notice").map((c) => (
                <option key={c.key} value={c.key}>{c.label}</option>
              ))}
            </select>
            {isStaffRole(profile?.role) && (
              <div className="flex gap-3">
                <label className="flex cursor-pointer items-center gap-2 rounded-2xl border border-white/10 bg-black/30 px-4 py-3 text-sm">
                  <input type="checkbox" checked={isNotice} onChange={(e) => setIsNotice(e.target.checked)} />
                  공지
                </label>
                <label className={cn("flex cursor-pointer items-center gap-2 rounded-2xl border border-white/10 bg-black/30 px-4 py-3 text-sm", !isNotice && "opacity-40 cursor-not-allowed")}>
                  <input type="checkbox" checked={isPinned} onChange={(e) => setIsPinned(e.target.checked)} disabled={!isNotice} />
                  고정
                </label>
              </div>
            )}
          </div>

          <input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="제목"
            className="w-full rounded-2xl px-5 py-4 text-sm font-semibold text-white outline-none transition-all placeholder:text-stone-600"
            style={{ background: "rgba(255,255,255,0.04)", border: "1px solid rgba(255,255,255,0.09)" }}
            onFocus={e => { e.currentTarget.style.borderColor=`rgba(var(--ga-r400,167,139,250),0.45)`; e.currentTarget.style.boxShadow=`0 0 0 3px rgba(var(--ga-r400,167,139,250),0.12)`; }}
            onBlur={e => { e.currentTarget.style.borderColor="rgba(255,255,255,0.09)"; e.currentTarget.style.boxShadow="none"; }}
          />

          <textarea
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="내용을 입력해줘"
            rows={6}
            className="w-full resize-none rounded-2xl px-5 py-4 text-sm text-white outline-none transition-all placeholder:text-stone-600"
            style={{ background: "rgba(255,255,255,0.04)", border: "1px solid rgba(255,255,255,0.09)" }}
            onFocus={e => { e.currentTarget.style.borderColor=`rgba(var(--ga-r400,167,139,250),0.45)`; e.currentTarget.style.boxShadow=`0 0 0 3px rgba(var(--ga-r400,167,139,250),0.12)`; }}
            onBlur={e => { e.currentTarget.style.borderColor="rgba(255,255,255,0.09)"; e.currentTarget.style.boxShadow="none"; }}
          />

          {/* 유튜브 URL */}
          <div className="space-y-2">
            <input
              value={youtubeUrl}
              onChange={(e) => setYoutubeUrl(e.target.value)}
              placeholder="YouTube URL (선택) — 붙여넣으면 자동 임베드"
              className="w-full rounded-2xl px-5 py-3.5 text-sm text-white outline-none transition-all placeholder:text-stone-600"
              style={{ background: "rgba(255,255,255,0.04)", border: "1px solid rgba(255,255,255,0.09)" }}
              onFocus={e => { e.currentTarget.style.borderColor=`rgba(var(--ga-r400,167,139,250),0.45)`; e.currentTarget.style.boxShadow=`0 0 0 3px rgba(var(--ga-r400,167,139,250),0.12)`; }}
              onBlur={e => { e.currentTarget.style.borderColor="rgba(255,255,255,0.09)"; e.currentTarget.style.boxShadow="none"; }}
            />
            {ytId && (
              <div className="overflow-hidden rounded-2xl border border-white/10 aspect-video">
                <iframe src={`https://www.youtube.com/embed/${ytId}`} className="w-full h-full" allowFullScreen />
              </div>
            )}
          </div>

          <ImageUploader label="이미지 첨부 (선택)" onUpload={(url: string) => setImgUrl(url)} />
          {imgUrl && (
            <div className="rounded-2xl border border-white/10 bg-black/30 p-3">
              <img src={imgUrl} className="w-full max-h-56 object-cover rounded-xl" />
            </div>
          )}

          <button
            onClick={handlePost}
            disabled={submitting}
            className="w-full rounded-2xl py-4 font-semibold tracking-wide text-white transition-all disabled:opacity-60 flex items-center justify-center gap-2"
            style={{
              background: `linear-gradient(135deg, var(--ga-400,#a78bfa), var(--ga-500,#8b5cf6))`,
              boxShadow: `var(--ga-shadow-btn,0 4px 16px rgba(139,92,246,0.35))`,
            }}
          >
            <Send size={16} />
            {submitting ? "등록 중..." : "게시하기"}
          </button>
        </div>
      </div>
        </div>{/* /px-7 py-6 */}
    </motion.div>
  );
};



const Auth = ({ mode, setMode }: any) => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [nickname, setNickname] = useState("");

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      if (mode === "signup") {
        const { data, error } = await supabase.auth.signUp({
          email,
          password,
          options: { data: { nickname } },
        });

        if (error) throw error;

        // 이메일 중복: signUp이 에러 없이 성공했지만 identities가 비어있는 경우
        if (data?.user && Array.isArray(data.user.identities) && data.user.identities.length === 0) {
          showToast("이미 가입된 이메일입니다. 로그인 해주세요.", "error");
          setMode("login");
          return;
        }

        await supabase.from("profiles").insert([
          {
            id: data.user?.id,
            nickname,
            grade: "신입",
          },
        ]);

        showToast("회원가입 성공! 이메일을 확인하세요.", "success");
        setMode("login");
      } else {
        const { error } = await supabase.auth.signInWithPassword({ email, password });
        if (error) throw error;
        setMode("home");
      }
    } catch (err: any) {
      // 가독성 좋은 한국어 에러 메시지
      const raw = String(err?.message || "");
      let friendly = raw;
      if (/already registered|already exists|User already/i.test(raw)) {
        friendly = "이미 가입된 이메일입니다. 로그인 해주세요.";
        setMode("login");
      } else if (/invalid login credentials|invalid_grant/i.test(raw)) {
        friendly = "이메일 또는 비밀번호가 올바르지 않습니다.";
      } else if (/email.*invalid|invalid.*email/i.test(raw)) {
        friendly = "올바른 이메일 형식이 아닙니다.";
      } else if (/password.*(short|6 characters|weak)/i.test(raw)) {
        friendly = "비밀번호는 최소 6자 이상이어야 합니다.";
      } else if (/rate limit|too many/i.test(raw)) {
        friendly = "요청이 너무 많습니다. 잠시 후 다시 시도해주세요.";
      }
      showToast(friendly, "error");
    }
  };

  return (
    <div className="max-w-md mx-auto py-32 px-4">
      <div className="p-12 rounded-[4rem] border border-white/10 bg-[#0f0f0f] shadow-2xl relative overflow-hidden text-center">
        <div className="absolute top-0 left-0 w-full h-px" style={{ background: `linear-gradient(90deg,transparent,rgba(var(--ga-r400,167,139,250),0.65) 40%,rgba(240,180,41,0.35) 65%,transparent)` }} />
        <h2 className="text-5xl font-semibold mb-2 tracking-tight uppercase">
          {mode === "login" ? "Sign In" : "Join Us"}
        </h2>
        <p className="text-slate-600 text-[10px] font-semibold tracking-[0.4em] mb-12 uppercase">
          Authentication Required
        </p>

        <form onSubmit={handleAuth} className="space-y-5 text-left">
          <input
            type="email"
            placeholder="E-MAIL"
            className="w-full bg-black border border-white/10 p-5 rounded-3xl focus:outline-none focus:border-amber-400 text-sm tracking-widest font-semibold text-white"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
          />

          <input
            type="password"
            placeholder="PASSWORD"
            className="w-full bg-black border border-white/10 p-5 rounded-3xl focus:outline-none focus:border-amber-400 text-sm tracking-widest font-semibold text-white"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />

          {mode === "signup" && (
            <input
              type="text"
              placeholder="NICKNAME"
              className="w-full bg-black border border-white/10 p-5 rounded-3xl focus:outline-none focus:border-amber-400 text-sm tracking-widest font-semibold text-white"
              value={nickname}
              onChange={(e) => setNickname(e.target.value)}
              required
            />
          )}

          <button
            type="submit"
            className="w-full bg-amber-500 p-6 rounded-3xl font-semibold uppercase tracking-[0.3em] mt-6 hover:bg-amber-400 transition-colors shadow-lg shadow-amber-500/20 active:scale-95 text-white"
          >
            Proceed
          </button>
        </form>

        <button
          onClick={() => setMode(mode === "login" ? "signup" : "login")}
          className="mt-8 text-[10px] font-semibold text-slate-600 hover:text-white uppercase transition-all"
        >
          Switch to {mode === "login" ? "signup" : "login"}
        </button>
      </div>
    </div>
  );
};



// ══════════════════════════════════════════════════════════
//  ArmoryViewModal — 마이룸 캐릭터 전투정보실 뷰어
// ══════════════════════════════════════════════════════════
type ArmoryTab = "equipment" | "skills" | "arkgrid" | "gems" | "avatars" | "expedition";


// ══════════════════════════════════════════════════════════
//  RaidMemoPanel — 마이룸 레이드 메모 (갤러리 + 모달)
// ══════════════════════════════════════════════════════════
type MemoItem = { id: string; hp_line: string; pattern: string };
type RaidMemo = { raid_name: string; image_url: string; memo_items: MemoItem[]; updated_at?: string };


// ═══════════════════════════════════════════════════════════
// ── 레이드 메모 태그 시스템 ────────────────────────────────
// ═══════════════════════════════════════════════════════════
type MemoTagDef = {
  label: string;
  bg: string;
  text: string;
  border: string;
  hoverBg: string;
};

const MEMO_TAGS: MemoTagDef[] = [
  {
    label: "카운터",
    bg: "bg-blue-400/15",
    text: "text-blue-300",
    border: "border-blue-400/25",
    hoverBg: "hover:bg-blue-400/25",
  },
  {
    label: "저스트가드",
    bg: "bg-yellow-400/15",
    text: "text-yellow-300",
    border: "border-yellow-400/25",
    hoverBg: "hover:bg-yellow-400/25",
  },
  {
    label: "협동카운터",
    bg: "bg-violet-400/15",
    text: "text-violet-300",
    border: "border-violet-400/25",
    hoverBg: "hover:bg-violet-400/25",
  },
  {
    label: "무력",
    bg: "bg-orange-400/15",
    text: "text-orange-300",
    border: "border-orange-400/25",
    hoverBg: "hover:bg-orange-400/25",
  },
];

// [태그] 문법을 파싱해서 색상 뱃지로 렌더링
const renderMemoPattern = (text: string): React.ReactNode => {
  if (!text) return <span className="text-stone-500 italic">내용 없음</span>;

  const tagRegex = /\[([^\]]+)\]/g;
  const segments: React.ReactNode[] = [];
  let lastIndex = 0;
  let match;
  let key = 0;

  while ((match = tagRegex.exec(text)) !== null) {
    // 태그 앞 일반 텍스트
    if (match.index > lastIndex) {
      const plain = text.slice(lastIndex, match.index);
      segments.push(<React.Fragment key={key++}>{plain}</React.Fragment>);
    }

    const tagLabel = match[1];
    const tagDef = MEMO_TAGS.find(t => t.label === tagLabel);

    if (tagDef) {
      segments.push(
        <span
          key={key++}
          className={cn(
            "inline-flex items-center rounded-full border px-2 py-0.5 text-[11px] font-bold mx-0.5 align-middle",
            tagDef.bg, tagDef.text, tagDef.border
          )}
        >
          {tagLabel}
        </span>
      );
    } else {
      // 알 수 없는 태그는 그냥 텍스트로
      segments.push(<React.Fragment key={key++}>{match[0]}</React.Fragment>);
    }

    lastIndex = match.index + match[0].length;
  }

  // 남은 텍스트
  if (lastIndex < text.length) {
    segments.push(<React.Fragment key={key++}>{text.slice(lastIndex)}</React.Fragment>);
  }

  return segments;
};
// ── End Memo Tag System ──────────────────────────────────────

// ── 메모 편집 모달 ─────────────────────────────────────────
const RaidMemoEditModal = ({
  memo,
  raids,
  user,
  onClose,
  onSaved,
}: {
  memo: RaidMemo | null; // null = 신규
  raids: any[];
  user: any;
  onClose: () => void;
  onSaved: () => void;
}) => {
  const { theme } = useTheme();
  const isLight = theme === "light";

  const [selectedRaid, setSelectedRaid] = useState(memo?.raid_name || "");
  const [memoItems, setMemoItems] = useState<MemoItem[]>(memo?.memo_items || []);
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const textareaRefs = useRef<Map<string, HTMLTextAreaElement>>(new Map());

  const raidImage = raids.find((r: any) => r.name === selectedRaid)?.image_url || "";

  const newItem = (): MemoItem => ({ id: crypto.randomUUID(), hp_line: "", pattern: "" });
  const addItem = () => setMemoItems(p => [...p, newItem()]);
  const updateItem = (id: string, field: keyof MemoItem, value: string) =>
    setMemoItems(p => p.map(item => item.id === id ? { ...item, [field]: value } : item));
  const removeItem = (id: string) =>
    setMemoItems(p => p.filter(item => item.id !== id));

  // 태그를 textarea 커서 위치에 삽입
  const insertTag = (itemId: string, tagLabel: string) => {
    const el = textareaRefs.current.get(itemId);
    const insertText = `[${tagLabel}]`;
    if (!el) {
      // ref 없으면 끝에 붙임
      updateItem(itemId, "pattern", (memoItems.find(i => i.id === itemId)?.pattern || "") + insertText);
      return;
    }
    const start = el.selectionStart ?? el.value.length;
    const end   = el.selectionEnd   ?? el.value.length;
    const before = el.value.slice(0, start);
    const after  = el.value.slice(end);
    const next = before + insertText + after;
    updateItem(itemId, "pattern", next);
    // 커서를 삽입 텍스트 뒤로
    requestAnimationFrame(() => {
      el.focus();
      el.setSelectionRange(start + insertText.length, start + insertText.length);
    });
  };

  const saveMemo = async () => {
    if (!selectedRaid || !user?.id) return;
    setSaving(true);
    const { error } = await supabase.from("raid_memos").upsert(
      { user_id: user.id, raid_name: selectedRaid, memo_items: memoItems, updated_at: new Date().toISOString() },
      { onConflict: "user_id,raid_name" }
    );
    setSaving(false);
    if (error) { showToast("저장 실패: " + error.message, "error"); return; }
    showToast("메모 저장 완료!", "success");
    onSaved();
    onClose();
  };

  const deleteMemo = async () => {
    if (!memo?.raid_name || !user?.id) return;
    if (!confirm("이 레이드 메모를 삭제하시겠습니까?")) return;
    setDeleting(true);
    const { error } = await supabase.from("raid_memos")
      .delete().eq("user_id", user.id).eq("raid_name", memo.raid_name);
    setDeleting(false);
    if (error) { showToast("삭제 실패", "error"); return; }
    showToast("메모 삭제 완료", "success");
    onSaved();
    onClose();
  };

  const panelBg = isLight ? "bg-[#fdfaf4] border-amber-200/40" : "bg-[#0d1526]/97 border-[rgba(167,139,250,0.18)]";
  const inputCl = isLight
    ? "border-amber-200/40 bg-white/80 text-[#1a1208] placeholder-stone-400 focus:border-amber-400/50"
    : "border-white/10 bg-black/40 text-white placeholder-stone-600 focus:border-amber-400/30";

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 z-[350] flex items-center justify-center bg-black/75 p-4 backdrop-blur-xl"
      onClick={onClose}
    >
      <motion.div
        initial={{ opacity: 0, y: 20, scale: 0.97 }}
        animate={{ opacity: 1, y: 0, scale: 1 }}
        exit={{ opacity: 0, y: 12, scale: 0.97 }}
        transition={{ duration: 0.2 }}
        className={cn(
          "relative w-full max-w-2xl overflow-hidden rounded-[2rem] border shadow-[0_32px_80px_rgba(0,0,0,0.6)] backdrop-blur-2xl",
          panelBg
        )}
        style={{ maxHeight: "90vh" }}
        onClick={e => e.stopPropagation()}
      >
        {/* 헤더 */}
        <div className={cn(
          "flex items-center justify-between border-b px-6 py-5",
          isLight ? "border-amber-200/30 bg-amber-50/40" : "border-white/8 bg-white/[0.02]"
        )}>
          <div className="flex items-center gap-3">
            {raidImage ? (
              <img src={raidImage} alt="" className="h-11 w-11 rounded-2xl border border-white/10 object-cover" />
            ) : (
              <div className="flex h-11 w-11 items-center justify-center rounded-2xl border border-violet-400/20 bg-violet-400/10">
                <Sparkles size={16} className="text-violet-300" />
              </div>
            )}
            <div>
              <div className={cn("text-lg font-bold", isLight ? "text-[#1a1208]" : "text-white")}>
                {memo ? "메모 수정" : "레이드 메모 추가"}
              </div>
              <div className={cn("text-[11px]", isLight ? "text-stone-500" : "text-stone-400")}>
                HP 구간별 기믹 / 패턴을 기록해봐
              </div>
            </div>
          </div>
          <button
            onClick={onClose}
            className={cn(
              "flex h-9 w-9 items-center justify-center rounded-xl border transition-all",
              isLight ? "border-amber-200/40 text-stone-400 hover:bg-amber-100" : "border-white/10 text-stone-400 hover:bg-white/10 hover:text-white"
            )}
          >
            <X size={16} />
          </button>
        </div>

        {/* 바디 */}
        <div className="overflow-y-auto px-6 py-5 space-y-4" style={{ maxHeight: "calc(90vh - 200px)" }}>
          {/* 레이드 선택 (신규 시에만) */}
          {!memo && (
            <div className="space-y-2">
              <label className={cn("text-[10px] font-bold uppercase tracking-widest", isLight ? "text-stone-500" : "text-stone-500")}>레이드 선택</label>
              <select
                value={selectedRaid}
                onChange={e => setSelectedRaid(e.target.value)}
                className={cn("w-full rounded-2xl border px-4 py-3 text-sm outline-none transition-all appearance-none cursor-pointer", inputCl)}
              >
                <option value="">레이드를 선택하세요</option>
                {raids.map((r: any) => (
                  <option key={r.id} value={r.name}>{r.name}</option>
                ))}
              </select>
            </div>
          )}

          {/* 메모 항목 */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <label className={cn("text-[10px] font-bold uppercase tracking-widest", isLight ? "text-stone-500" : "text-stone-500")}>기믹 메모</label>
              <span className={cn("text-[10px]", isLight ? "text-stone-400" : "text-stone-600")}>{memoItems.length}개</span>
            </div>

            {memoItems.length === 0 && (
              <div className={cn(
                "rounded-2xl border border-dashed py-8 text-center text-sm",
                isLight ? "border-amber-200/30 text-stone-400" : "border-white/8 text-stone-500"
              )}>
                아래 버튼으로 기믹 메모를 추가해봐
              </div>
            )}

            {memoItems.map((item, idx) => (
              <div
                key={item.id}
                className={cn(
                  "rounded-2xl border px-4 py-3.5 transition-all",
                  isLight ? "border-amber-200/25 bg-white/60" : "border-white/8 bg-white/[0.025]"
                )}
              >
                {/* 입력 행 */}
                <div className="flex items-start gap-3">
                  <div className="flex h-6 w-6 shrink-0 items-center justify-center rounded-lg bg-amber-400/15 text-[11px] font-bold text-amber-300 mt-2">
                    {idx + 1}
                  </div>
                  <input
                    value={item.hp_line}
                    onChange={e => updateItem(item.id, "hp_line", e.target.value)}
                    placeholder="HP 구간 (예: 30%)"
                    className={cn("w-28 shrink-0 rounded-xl border px-3 py-2 text-xs font-bold outline-none transition-all", inputCl)}
                  />
                  <textarea
                    ref={el => {
                      if (el) textareaRefs.current.set(item.id, el);
                      else textareaRefs.current.delete(item.id);
                    }}
                    value={item.pattern}
                    onChange={e => updateItem(item.id, "pattern", e.target.value)}
                    placeholder="기믹 / 패턴 설명 (예: [카운터] 후 [무력])"
                    rows={2}
                    className={cn("flex-1 resize-none rounded-xl border px-3 py-2 text-xs outline-none transition-all leading-5", inputCl)}
                  />
                  <button
                    onClick={() => removeItem(item.id)}
                    className={cn(
                      "mt-1 flex h-8 w-8 shrink-0 items-center justify-center rounded-xl border transition-all",
                      isLight
                        ? "border-rose-200/40 text-rose-400 hover:bg-rose-50"
                        : "border-white/10 text-stone-500 hover:border-rose-400/30 hover:bg-rose-400/[0.08] hover:text-rose-300"
                    )}
                  >
                    <X size={13} />
                  </button>
                </div>

                {/* 태그 빠른 삽입 버튼 */}
                <div className="mt-2 ml-9 flex flex-wrap gap-1.5">
                  <span className={cn("text-[9px] font-semibold uppercase tracking-widest self-center mr-1", isLight ? "text-stone-400" : "text-stone-600")}>
                    태그 삽입
                  </span>
                  {MEMO_TAGS.map(tag => (
                    <button
                      key={tag.label}
                      type="button"
                      onClick={() => insertTag(item.id, tag.label)}
                      className={cn(
                        "inline-flex items-center rounded-full border px-2.5 py-1 text-[11px] font-bold transition-all",
                        tag.bg, tag.text, tag.border, tag.hoverBg
                      )}
                      title={`[${tag.label}] 삽입`}
                    >
                      {tag.label}
                    </button>
                  ))}
                </div>
              </div>
            ))}

            <button
              onClick={addItem}
              className={cn(
                "w-full flex items-center justify-center gap-2 rounded-2xl border border-dashed py-3 text-sm font-semibold transition-all",
                isLight
                  ? "border-amber-300/40 text-amber-600 hover:bg-amber-50"
                  : "border-white/12 text-stone-500 hover:border-amber-400/25 hover:text-amber-300 hover:bg-amber-400/[0.04]"
              )}
            >
              <Plus size={15} /> 기믹 항목 추가
            </button>
          </div>
        </div>

        {/* 푸터 */}
        <div className={cn("flex gap-2 border-t px-6 py-4", isLight ? "border-amber-200/30" : "border-white/8")}>
          <button
            onClick={saveMemo}
            disabled={saving || !selectedRaid}
            className="flex-1 rounded-[1.2rem] bg-gradient-to-r from-amber-500 to-amber-400 px-4 py-3 text-sm font-bold text-slate-950 shadow-[0_4px_16px_rgba(245,158,11,0.3)] transition-all hover:brightness-110 disabled:opacity-50"
          >
            {saving ? "저장 중..." : "💾 저장"}
          </button>
          {memo && (
            <button
              onClick={deleteMemo}
              disabled={deleting}
              className="rounded-[1.2rem] border border-rose-400/20 bg-rose-400/10 px-4 py-3 text-sm font-semibold text-rose-300 transition-all hover:bg-rose-400/16 disabled:opacity-50"
            >
              {deleting ? "삭제 중..." : "삭제"}
            </button>
          )}
          <button
            onClick={onClose}
            className={cn(
              "rounded-[1.2rem] border px-4 py-3 text-sm font-semibold transition-all",
              isLight ? "border-amber-200/40 text-stone-500 hover:bg-amber-50" : "border-white/10 text-slate-300 hover:bg-white/[0.06]"
            )}
          >
            닫기
          </button>
        </div>
      </motion.div>
    </motion.div>
  );
};

